  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: grecia
insert into public.lessons (topic_id, title, body, position, published)
select id, 'Grecia arcaica y clásica', '[{"type":"section","title":"Del colapso micénico a la polis","text":"Hacia 1200 a. C. se derrumbaron los palacios micénicos, con su escritura silábica (Lineal B), su burocracia redistributiva y su economía centralizada. El colapso formó parte del hundimiento general del Bronce Final en el Mediterráneo oriental. Grecia perdió la escritura durante unos cuatro siglos, y con ella la administración palacial: no hay archivos, ni grandes obras, ni comercio de larga distancia comparable.\n\nDe esa discontinuidad surgió algo distinto. Cuando las comunidades se reorganizaron, no reconstruyeron palacios: construyeron poleis. Una polis no es simplemente una ciudad; es una comunidad de ciudadanos —un cuerpo político— con su territorio (chora), su ágora, sus cultos y sus instituciones. Aristóteles lo formuló con precisión: la polis es una comunidad de ciudadanos, no un lugar. Por eso los griegos decían «los atenienses» y no «Atenas» al hablar de decisiones políticas.\n\nLa recuperación de la escritura fue igualmente reveladora. Los griegos adoptaron el alfabeto fenicio hacia el siglo IX-VIII a. C., pero introdujeron una modificación decisiva: asignaron signos a las vocales. El resultado fue un sistema de unas veinticuatro letras, aprendible en semanas y no en años, frente al centenar largo de signos del cuneiforme o del jeroglífico. Ese abaratamiento de la alfabetización tuvo consecuencias políticas: las leyes podían exponerse por escrito y ser verificadas por cualquiera.\n\nLa gran colonización (c. 750-550 a. C.) llevó fundaciones griegas desde el mar Negro hasta el sur de Francia y la costa ibérica —Emporion, la actual Empúries, entre ellas—. Sus causas fueron sobre todo agrarias: escasez de tierra cultivable (stenochoria), presión demográfica y conflictos internos. Cada colonia era, desde su fundación, una polis independiente y no una posesión de la metrópolis: un rasgo que la distingue radicalmente del colonialismo moderno.","textEso":"Hacia 1200 a. C. los palacios micénicos se derrumbaron y con ellos desapareció la escritura, la administración y el comercio a gran distancia. Siguieron unos siglos oscuros de los que sabemos poco. Cuando Grecia reaparece, hacia el siglo VIII a. C., lo hace con una forma política nueva: la polis, una ciudad independiente con su territorio, sus leyes y sus dioses. No hubo un Estado griego: hubo cientos de polis que compartían lengua y religión pero se gobernaban por separado.","textBachillerato":"El colapso de los palacios micénicos hacia 1200 a. C. formó parte de una crisis mediterránea general que afectó también a hititas y egipcios. Sus causas siguen discutiéndose: sequías documentadas en registros climáticos, movimientos de población, fallos en cadena de economías palaciales muy centralizadas. Lo seguro es el resultado: desaparecen la escritura lineal B, la administración y las redes de intercambio.\n\nCuando Grecia vuelve a ser visible, en el siglo VIII a. C., lo hace con una organización distinta. La polis no es solo una ciudad: es una comunidad de ciudadanos con territorio, culto y leyes propias, y con la idea de que las decisiones se toman en un espacio público. Fueron cientos, muy distintas entre sí, y nunca formaron un Estado común. Esa fragmentación, favorecida por una geografía de valles y islas, explica tanto la competencia constante como la variedad de experimentos políticos.","callout":"Aristóteles define al ser humano como zoon politikon: el animal que vive en polis. La traducción «animal político» pierde el matiz: no significa aficionado a la política, sino incapaz de realizarse fuera de una comunidad de ciudadanos."},{"type":"section","title":"La crisis arcaica: hoplitas, deudas y legisladores","text":"Los siglos VII y VI a. C. fueron de tensión social aguda. La concentración de tierra en manos aristocráticas y la práctica del préstamo con garantía personal produjeron una masa de campesinos endeudados que podían acabar esclavizados por sus propios acreedores. La crisis es documentada por los poemas de Solón y por Hesíodo, cuyos *Trabajos y días* describen desde abajo la dureza del campesinado y la parcialidad de los «reyes devoradores de regalos».\n\nEn paralelo se transformó la guerra. La falange hoplítica —formación cerrada de infantes con escudo redondo, lanza y coraza— sustituyó al combate individual de campeones aristocráticos. Su eficacia dependía de la cohesión: cada hombre protegía con su escudo el flanco derecho del vecino. Los hoplitas se costeaban el equipo, lo que los situaba en un estrato acomodado pero no aristocrático.\n\nLa llamada «tesis hoplítica», formulada por Aristóteles y desarrollada por historiadores modernos, sostiene que quienes combatían en la falange acabaron reclamando participación política proporcional a su contribución militar. La crítica reciente —Hans van Wees y Kurt Raaflaub— ha discutido tanto la cronología como el automatismo del vínculo: la falange se desarrolló de forma gradual, y muchas poleis con ejército hoplítico siguieron siendo oligarquías.\n\nLa respuesta a la crisis fueron los legisladores y los tiranos. Dracón (621 a. C.) puso las leyes por escrito, y aunque su severidad hizo proverbial el adjetivo «draconiano», la simple publicidad de la norma limitaba la arbitrariedad de los jueces aristocráticos. Solón (594 a. C.) fue más lejos: canceló las deudas vigentes (seisachtheia), prohibió la esclavitud por deudas de ciudadanos atenienses, y estructuró la participación política según la renta agraria, no según el nacimiento. Fue una reforma censitaria, no democrática, pero rompió el monopolio del linaje.\n\nLa tiranía griega arcaica no equivale al sentido moderno de la palabra. Los tiranos eran normalmente aristócratas que tomaban el poder al margen de la ley apoyándose en el descontento popular. Los Pisistrátidas en Atenas promovieron fiestas cívicas, obras públicas y cultos ciudadanos que, paradójicamente, debilitaron las redes clientelares de la nobleza y prepararon el terreno para la democracia.","textEso":"El siglo VII a. C. fue conflictivo. La población crecía, la tierra no daba para todos y muchos campesinos se endeudaban hasta perder la libertad. De ahí salieron dos salidas: fundar colonias por todo el Mediterráneo, de Ampurias a Crimea, y cambiar las leyes en casa. Al mismo tiempo cambió la guerra: el hoplita, el soldado de infantería con escudo y lanza que lucha en formación, hacía que la defensa dependiera de miles de ciudadanos y no de unos pocos aristócratas a caballo. Quien defiende la ciudad acaba pidiendo decidir sobre ella.","textBachillerato":"El periodo arcaico concentra una crisis social de fondo: crecimiento demográfico, tierra limitada y un régimen de deuda que podía terminar en esclavitud por impago. Las dos respuestas fueron la colonización, que llevó griegos desde la península ibérica hasta el mar Negro, y la legislación escrita, que fijaba por primera vez normas fuera del arbitrio aristocrático.\n\nEn paralelo cambia la guerra. La falange hoplítica traslada la eficacia militar del combate individual del aristócrata a caballo a la cohesión de una línea de ciudadanos con escudo y lanza. Durante mucho tiempo se explicó la apertura política como consecuencia directa de ese cambio, y hoy esa relación se discute: la cronología no encaja del todo y la reforma militar pudo ser más gradual. Pero la conexión general se sostiene: donde la defensa depende de miles de propietarios medios, resulta difícil excluirlos de la decisión política.","callout":null},{"type":"section","title":"La democracia ateniense: mecánica y alcance","text":"Las reformas de Clístenes en 508/507 a. C. reorganizaron el cuerpo cívico sobre una base deliberadamente artificial. Sustituyó las cuatro tribus tradicionales de parentesco por diez tribus nuevas, cada una compuesta por demos de tres zonas distintas del Ática —costa, ciudad e interior—. El objetivo era romper las lealtades regionales y clientelares: la unidad política pasó a ser el demo de residencia, y los ciudadanos empezaron a identificarse por su demótico y no por su linaje.\n\nEl sistema resultante descansaba en tres órganos. La Ekklesía, asamblea abierta a todos los ciudadanos varones, se reunía unas cuarenta veces al año en la Pnyx y decidía leyes, guerra, paz y finanzas. La Boulé, consejo de quinientos miembros elegidos por sorteo, preparaba el orden del día y gestionaba la administración cotidiana. Los tribunales populares (Heliea), con jurados de centenares de ciudadanos también sorteados, juzgaban sin jueces profesionales.\n\nEl rasgo más ajeno a nuestra sensibilidad es el sorteo. Para los griegos, la elección era un procedimiento aristocrático —selecciona a los mejores o a los más conocidos— mientras que el sorteo era el procedimiento democrático, porque garantizaba igualdad efectiva de acceso al cargo. Solo los puestos que exigían competencia técnica, como el mando militar (estrategos), se cubrían por elección; y no es casual que fuera la estrategia el cargo desde el que Pericles gobernó de hecho durante décadas.\n\nA partir de Pericles se introdujo la misthophoría, un pago por el ejercicio de cargos y por asistir a los tribunales. La medida es decisiva: sin retribución, solo los acomodados podían permitirse dedicar días a la política. Aristóteles señala precisamente esto como el mecanismo que hizo real, y no solo formal, la participación de los pobres.\n\nLos límites del sistema son igual de importantes que sus mecanismos. La ciudadanía excluía a mujeres, a metecos (extranjeros residentes, muchos de ellos ricos y establecidos durante generaciones) y a esclavos. Las estimaciones más aceptadas para la Atenas del siglo V dan entre 30.000 y 60.000 ciudadanos varones sobre una población total de entre 250.000 y 300.000 personas: entre un 10 % y un 20 % del total. Y la ley de ciudadanía de Pericles (451 a. C.), que exigía madre y padre atenienses, restringió aún más el acceso.","textEso":"La democracia ateniense se construyó en etapas, con Solón, Clístenes y Pericles. Funcionaba así: una asamblea abierta a todos los ciudadanos decidía las leyes y la guerra; un consejo de 500 miembros elegidos a sorteo preparaba los asuntos; los tribunales eran jurados populares de cientos de personas, también por sorteo. Casi todos los cargos se sorteaban, no se votaban, porque elegir favorecía a los ricos y conocidos. Pero ciudadanos eran solo los varones adultos de padre ateniense: quedaban fuera mujeres, extranjeros y esclavos, que eran la mayoría de la población.","textBachillerato":"La democracia ateniense se construye en etapas: Solón suprime la esclavitud por deudas y gradúa los derechos por renta; Clístenes reorganiza el cuerpo cívico en demos y tribus artificiales para romper las clientelas aristocráticas; con Efialtes y Pericles se amplían las competencias de la asamblea y se retribuyen los cargos.\n\nSu mecánica es más radical que cualquier democracia actual. La Asamblea decide directamente leyes, guerra y tratados. El Consejo de los Quinientos, sorteado anualmente, fija el orden del día. Los tribunales son jurados populares de cientos de miembros sorteados, sin jueces profesionales. Y el sorteo, no la elección, es el procedimiento normal de acceso al cargo, porque se entendía que elegir favorecía al rico y al notable. Todo ello conviviendo con una definición de ciudadanía estrechísima: varones adultos de padre y, tras 451 a. C., también madre ateniense. Mujeres, metecos y esclavos, la mayoría de los habitantes, quedaban fuera.","callout":"El ostracismo permitía desterrar diez años a un ciudadano sin acusarlo de delito, mediante votación con fragmentos de cerámica. Era un mecanismo preventivo contra la concentración de poder, no una pena: el desterrado conservaba sus bienes."},{"type":"section","title":"Esparta: la anomalía que fascinó a la tradición","text":"Esparta ha sido, desde la Antigüedad, objeto de una idealización persistente que los historiadores llaman «el espejismo espartano». La imagen de una comunidad austera, igualitaria y perfectamente estable procede en gran medida de autores admiradores y externos —Jenofonte, Plutarco escribiendo siglos después— y de la ausencia de fuentes espartanas propias, ya que la ciudad no produjo casi literatura ni documentos.\n\nSu singularidad real era estructural. Esparta sometió a la vecina Mesenia y convirtió a su población en hilotas: una masa servil adscrita a la tierra, propiedad colectiva del Estado y no de particulares. Los hilotas superaban ampliamente en número a los espartiatas, y sostenían con su trabajo la dedicación militar exclusiva de estos. El sistema exigía represión permanente: los éforos declaraban formalmente la guerra a los hilotas cada año, y la kryptéia enviaba a jóvenes espartiatas a matar selectivamente a los hilotas más destacados.\n\nLa educación estatal (agogé) retiraba a los niños de sus familias a los siete años y los sometía a un entrenamiento colectivo de resistencia, disciplina y obediencia. El sistema político combinaba dos reyes hereditarios, un consejo de ancianos (gerusía), una asamblea de escasa capacidad de iniciativa y cinco éforos con amplios poderes de control anual.\n\nLas mujeres espartanas gozaban de una posición atípica en el mundo griego: recibían formación física, podían poseer y heredar tierras, y en época helenística Aristóteles calculaba que controlaban cerca de dos quintas partes del territorio. Aristóteles lo consideraba un defecto del régimen; para el historiador es un dato sobre las consecuencias de un sistema en el que los varones vivían prácticamente en cuartel.\n\nEl punto ciego de la idealización es demográfico. La rígida igualdad de lotes de tierra se erosionó por herencias y concentración, y el número de espartiatas de pleno derecho se desplomó: de unos 8.000 en las guerras médicas a poco más de mil en el siglo IV. La derrota ante Tebas en Leuctra (371 a. C.) y la subsiguiente liberación de Mesenia liquidaron la base económica del sistema. Esparta no cayó por decadencia moral, sino por agotamiento de su cuerpo de ciudadanos.","textEso":"Esparta siguió otro camino. Su sociedad se organizó en torno al entrenamiento militar: los niños salían de casa a los siete años, los ciudadanos adultos se dedicaban casi en exclusiva a la guerra y la economía la sostenían los ilotas, una población sometida y muy numerosa. Las mujeres espartanas tenían más libertad y más propiedad que las atenienses. El sistema funcionaba mientras la vigilancia sobre los ilotas se mantuviera, y buena parte de la política espartana se explica por ese miedo.","textBachillerato":"Esparta construyó un sistema orientado por completo al control interno. Su población sometida, los ilotas, era varias veces más numerosa que la de ciudadanos, y de ese desequilibrio derivan casi todos sus rasgos: la educación militar obligatoria desde la infancia, la vida comunitaria de los adultos, la prohibición de hecho de actividades económicas para el ciudadano y una política exterior prudente cuando había riesgo de revuelta.\n\nBuena parte de lo que creemos saber de Esparta procede de autores que no eran espartanos y que la admiraban o la usaban como contramodelo de Atenas. Esa construcción, el llamado espejismo espartano, siguió funcionando siglos después en discursos militaristas europeos. Dos datos suelen sorprender y están bien documentados: las mujeres espartanas disponían de propiedad y de una libertad de movimientos impensable en Atenas, y el cuerpo ciudadano se redujo tanto con el tiempo que acabó siendo un problema estratégico insalvable.","callout":null},{"type":"section","title":"Guerras médicas, imperio y guerra del Peloponeso","text":"Las guerras médicas enfrentaron a un conjunto de poleis con el Imperio persa aqueménida entre 490 y 479 a. C. La victoria griega —Maratón, Salamina, Platea— tuvo un efecto identitario enorme: consolidó la oposición conceptual entre «griegos» y «bárbaros» que antes era mucho menos nítida, y proporcionó a Atenas un prestigio y una flota decisivos.\n\nDe esa flota nació la Liga de Delos (478 a. C.), alianza defensiva con tesoro común en la isla de Delos. Su deriva es uno de los procesos mejor documentados de conversión de una alianza en imperio: Atenas trasladó el tesoro a la Acrópolis en 454 a. C., impuso el phoros como tributo, reprimió militarmente las secesiones (Naxos, Tasos, Samos), instaló guarniciones y colonos, y obligó a los aliados a litigar en tribunales atenienses. Tucídides lo dice sin eufemismos: era una tiranía.\n\nLa financiación del Partenón con fondos de la Liga ilustra la tensión. Los grandes programas constructivos de Pericles, que hoy leemos como cumbre del arte clásico, fueron pagados en parte con el tributo de ciudades aliadas y criticados en su momento por eso mismo.\n\nLa guerra del Peloponeso (431-404 a. C.) enfrentó a la Atenas marítima y democrática con la Esparta terrestre y oligárquica. Tucídides propone una explicación causal que sigue siendo un modelo de análisis: la causa verdadera fue el crecimiento del poder ateniense y el miedo que suscitó en Esparta, mientras que los incidentes de Corcira y Potidea fueron pretextos. La distinción entre causa profunda y ocasión inmediata es una de las aportaciones metodológicas fundacionales de la historiografía.\n\nLa guerra fue devastadora. La peste de 430-426 a. C. mató quizá a un tercio de la población ateniense, incluido Pericles. El diálogo de Melos, donde los atenienses justifican el exterminio de una ciudad neutral con el argumento de que «los fuertes hacen lo que pueden y los débiles sufren lo que deben», es el texto más citado sobre la lógica del poder desnudo. La expedición a Sicilia (415-413 a. C.) destruyó la flota y el ejército atenienses. La derrota final en 404 a. C. trajo la breve tiranía de los Treinta y, tras la restauración democrática, el proceso contra Sócrates en 399 a. C.","textEso":"A comienzos del siglo V a. C. el Imperio persa intentó dos veces someter a Grecia y fracasó: Maratón, Salamina y Platea. Tras la victoria, Atenas organizó una alianza para seguir la guerra, la Liga de Delos, y poco a poco la convirtió en su imperio: trasladó el tesoro común a Atenas y castigó a quien quiso salirse. Esparta y sus aliados reaccionaron y estalló la guerra del Peloponeso, veintisiete años de desgaste que terminó en 404 a. C. con la derrota de Atenas.","textBachillerato":"Las guerras médicas enfrentaron a un imperio persa enorme con un conjunto de polis que solo en parte se coordinaron. Maratón en 490 a. C., y Salamina y Platea en 480-479 a. C., fueron victorias griegas que la tradición posterior convirtió en el triunfo de la libertad sobre el despotismo: una lectura que procede de los propios vencedores y que conviene manejar con cautela.\n\nLa consecuencia fue la hegemonía ateniense. La Liga de Delos, creada para continuar la guerra, se transformó en imperio: el tesoro común se trasladó a Atenas, las aportaciones se volvieron tributo y la secesión se castigó militarmente. Tucídides presenta la guerra del Peloponeso como resultado del miedo espartano a ese crecimiento. Los veintisiete años de conflicto, con la peste de Atenas, el desastre de Sicilia y la intervención persa financiando a Esparta, acabaron en 404 a. C. agotando a los dos bandos y abriendo el camino a Macedonia.","callout":"Tucídides afirma escribir «una posesión para siempre» y no una pieza de concurso. Su renuncia a la explicación sobrenatural y su atención a los intereses y al miedo lo convierten en fundador del análisis político."},{"type":"section","title":"Pensamiento, teatro y el legado discutible","text":"La filosofía griega nació en las colonias jonias con una pregunta cosmológica: de qué está hecho el mundo y por qué cambia. Tales, Anaximandro y Heráclito buscaron principios naturales sin recurrir a los dioses. El giro decisivo llegó con los sofistas y con Sócrates, que desplazaron la pregunta hacia lo humano: la justicia, la virtud, la ley, el mejor régimen.\n\nLos sofistas fueron maestros itinerantes que enseñaban retórica por dinero, algo indispensable en sociedades donde el poder se ejercía hablando en la asamblea y en los tribunales. Protágoras formuló el relativismo más citado de la Antigüedad —«el hombre es la medida de todas las cosas»— y la distinción entre physis (naturaleza) y nomos (convención) permitió por primera vez preguntarse si las leyes vigentes eran naturales o simplemente acordadas. La mala fama de los sofistas procede en buena medida de Platón, parte interesada en el debate.\n\nEl teatro ateniense era una institución cívica financiada por ciudadanos ricos mediante la coregía, con asistencia masiva y contenido explícitamente político. La tragedia planteaba en escena conflictos irresolubles entre deberes legítimos —la *Antígona* de Sófocles enfrenta la ley de la ciudad y la obligación religiosa familiar—, y la comedia de Aristófanes atacaba por su nombre a políticos vivos, a generales y al propio Sócrates. Que una democracia financiara la crítica más feroz de sí misma es un dato notable.\n\nEl legado griego debe manejarse con cuidado. Es habitual presentar a Grecia como «cuna de Occidente» en una línea continua hasta la democracia moderna. Esa genealogía es en buena medida una construcción del siglo XIX: la democracia ateniense era directa, no representativa; se basaba en el sorteo, que hoy no usamos; excluía a la mayoría de la población; y coexistía con la esclavitud, con el imperialismo y con la subordinación estricta de las mujeres. Además, la transmisión de los textos griegos a Europa pasó decisivamente por la traducción y el comentario árabes y por Bizancio, un recorrido que el relato de la continuidad directa suele omitir.\n\nReconocer eso no reduce la aportación griega, la precisa. Lo verdaderamente inédito no fue un conjunto de instituciones exportables, sino una práctica: someter las reglas de la vida común a discusión pública argumentada, y considerarlas modificables. Esa idea, y no el Partenón, es lo que sigue en uso.","textEso":"En ese mismo siglo, y en esas mismas ciudades, se inventaron la filosofía, la historia, la medicina y el teatro que seguimos leyendo: Sócrates, Platón y Aristóteles; Heródoto y Tucídides; Esquilo, Sófocles, Eurípides y Aristófanes. El legado es enorme, pero conviene mirarlo sin idealizarlo: esa misma sociedad se sostenía sobre la esclavitud y excluía de la política a más de la mitad de sus habitantes. Las dos cosas son verdad a la vez.","textBachillerato":"El siglo V y el IV a. C. producen una concentración extraordinaria de innovación intelectual: la filosofía de Sócrates, Platón y Aristóteles; la historia como investigación razonada con Heródoto y Tucídides; una medicina que busca causas naturales; la tragedia y la comedia como instituciones cívicas financiadas por la ciudad y vistas por miles de personas.\n\nEl legado es real, pero su lectura ha cambiado. Durante siglos se presentó a Grecia como cuna de la civilización occidental, una construcción que minimizaba cuánto debía a Egipto y a Oriente Próximo y que ocultaba que esa misma sociedad era esclavista y excluía de la política a la mayoría de sus habitantes. Sostener las dos cosas a la vez, la potencia del legado y los límites de la sociedad que lo produjo, es lo que distingue una lectura histórica de una celebración.","callout":null},{"type":"concepts","items":[{"term":"Polis","definition":"Comunidad de ciudadanos con territorio, culto e instituciones propias. No equivale a «ciudad»: es un cuerpo político."},{"term":"Hoplita","definition":"Infante pesado que combatía en falange cerrada y se costeaba su equipo."},{"term":"Seisachtheia","definition":"«Sacudida de cargas»: cancelación de deudas de Solón y prohibición de la esclavitud por deudas."},{"term":"Ekklesía","definition":"Asamblea de todos los ciudadanos atenienses; órgano soberano en leyes, guerra y finanzas."},{"term":"Boulé","definition":"Consejo de 500 miembros sorteados que preparaba el orden del día de la asamblea."},{"term":"Misthophoría","definition":"Retribución por ejercer cargos o formar parte de los jurados. Hizo viable la participación de los pobres."},{"term":"Ostracismo","definition":"Destierro preventivo de diez años decidido por votación, sin delito ni pérdida de bienes."},{"term":"Meteco","definition":"Extranjero residente en Atenas: libre, con obligaciones fiscales y militares, pero sin derechos políticos."},{"term":"Hilota","definition":"Población servil mesenia adscrita a la tierra, propiedad colectiva del Estado espartano."},{"term":"Agogé","definition":"Educación estatal espartana, colectiva y militarizada, desde los siete años."},{"term":"Physis / nomos","definition":"Naturaleza frente a convención. Distinción sofística que permitió cuestionar la legitimidad de las leyes."},{"term":"Phoros","definition":"Tributo pagado por los aliados a la Liga de Delos, convertido de hecho en impuesto imperial ateniense."}]},{"type":"debates","items":[{"question":"¿Provocó la falange hoplítica la ampliación de la participación política?","positions":[{"school":"Tesis hoplítica clásica (Aristóteles; Andrewes, Cartledge)","argument":"Quienes sostenían la defensa de la comunidad y se costeaban el armamento reclamaron derechos proporcionales a esa contribución. El paso del combate aristocrático a la falange explicaría la apertura de los regímenes arcaicos."},{"school":"Revisión gradualista (van Wees, Raaflaub)","argument":"La falange se formó de manera lenta y no marca una ruptura militar nítida. Además, numerosas poleis con ejército hoplítico permanecieron oligárquicas: la correlación entre forma de combate y forma de gobierno no se sostiene."}],"state":"La versión fuerte de la tesis está desacreditada. Se acepta que la participación militar fue un argumento político disponible, pero no un mecanismo automático: el resultado dependió de las luchas internas de cada polis."},{"question":"¿Fue la Liga de Delos una alianza o un imperio?","positions":[{"school":"Lectura defensiva","argument":"Nació como alianza voluntaria frente a Persia, con tesoro común y asamblea de aliados. Atenas aportaba la flota y proporcionaba seguridad efectiva en el Egeo, además de reprimir la piratería."},{"school":"Lectura imperial (Tucídides; Meiggs)","argument":"El traslado del tesoro a Atenas en 454, la conversión de la contribución en tributo, la represión armada de las secesiones, las guarniciones, las cleruquías y la obligación de litigar en Atenas configuran una dominación. El propio Tucídides la llama tiranía."}],"state":"Hay consenso en que la alianza derivó en imperio; se discute el ritmo y hasta qué punto los aliados obtenían contrapartidas reales (seguridad marítima, apoyo a facciones democráticas locales) que explicarían la relativa escasez de revueltas."},{"question":"¿Fue la esclavitud la condición material de la democracia ateniense?","positions":[{"school":"Dependencia estructural (Finley; Ste. Croix)","argument":"El ocio necesario para la participación política intensiva descansaba en el trabajo esclavo. Atenas fue una «sociedad esclavista» en sentido pleno: la esclavitud no era marginal, sino la base de la producción y de la renta de las clases propietarias."},{"school":"Matización (Wood)","argument":"El campesinado ateniense libre trabajaba su propia tierra y constituía el grueso del cuerpo cívico. La democracia se apoyaría más en la existencia de pequeños productores libres protegidos frente al endeudamiento que en el excedente esclavo."}],"state":"Nadie discute la centralidad de la esclavitud —las estimaciones oscilan entre 60.000 y 100.000 esclavos en el Ática—, pero sí su papel causal exacto. El debate se cruza con la discusión más amplia sobre la naturaleza de la economía antigua."}]},{"type":"timeline","items":[{"date":"c. 1200–1100 a. C.","event":"Colapso del mundo micénico; comienza la llamada Edad Oscura."},{"date":"c. 800 a. C.","event":"Adopción del alfabeto fenicio y formación de la polis; poemas homéricos."},{"date":"c. 750–550 a. C.","event":"Gran colonización: fundaciones desde el mar Negro hasta Iberia."},{"date":"621 a. C.","event":"Legislación de Dracón en Atenas."},{"date":"594 a. C.","event":"Reformas de Solón: abolición de la esclavitud por deudas."},{"date":"561–510 a. C.","event":"Tiranía de los Pisistrátidas en Atenas."},{"date":"508/507 a. C.","event":"Reformas de Clístenes: nace la democracia ateniense."},{"date":"490 a. C.","event":"Maratón: derrota del primer desembarco persa."},{"date":"480–479 a. C.","event":"Termópilas, Salamina y Platea; fin de la invasión de Jerjes."},{"date":"478 a. C.","event":"Fundación de la Liga de Delos, después imperio ateniense."},{"date":"461–429 a. C.","event":"Hegemonía política de Pericles; construcción del Partenón desde 447."},{"date":"431–404 a. C.","event":"Guerra del Peloponeso; derrota final de Atenas."},{"date":"399 a. C.","event":"Proceso y ejecución de Sócrates."},{"date":"338 a. C.","event":"Queronea: Filipo II de Macedonia impone su hegemonía."},{"date":"323 a. C.","event":"Muerte de Alejandro Magno; fin convencional del periodo clásico."}]},{"type":"sources","items":[{"author":"Homero","title":"Ilíada y Odisea","year":"c. s. VIII a. C.","kind":"primaria","note":"Fuente sobre valores aristocráticos; refleja una sociedad posterior a la micénica que describe."},{"author":"Hesíodo","title":"Trabajos y días","year":"c. 700 a. C.","kind":"primaria","note":"Visión campesina de la crisis agraria arcaica y de la justicia parcial de los poderosos."},{"author":"Heródoto","title":"Historias","year":"c. 430 a. C.","kind":"primaria","note":"Relato de las guerras médicas y etnografía del mundo conocido. Interés por las causas y por el otro."},{"author":"Tucídides","title":"Historia de la guerra del Peloponeso","year":"c. 400 a. C.","kind":"primaria","note":"Distingue causa profunda de pretexto. Diálogo de Melos y discurso fúnebre de Pericles."},{"author":"Aristóteles (o su escuela)","title":"Constitución de los atenienses","year":"c. 330 a. C.","kind":"primaria","note":"Descripción del funcionamiento institucional ateniense. Redescubierta en papiro en 1879."},{"author":"Aristófanes","title":"Las nubes, Los caballeros, Lisístrata","year":"423–411 a. C.","kind":"primaria","note":"Comedia política que ataca por su nombre a dirigentes vivos y al propio Sócrates."},{"author":"Moses I. Finley","title":"The Ancient Economy","year":"1973","kind":"estudio","note":"Modelo sustantivista de la economía antigua; central en el debate sobre esclavitud y mercado."},{"author":"Russell Meiggs","title":"The Athenian Empire","year":"1972","kind":"estudio","note":"Estudio de referencia sobre la conversión de la Liga de Delos en imperio."},{"author":"Paul Cartledge","title":"The Spartans","year":"2002","kind":"estudio","note":"Revisión crítica del «espejismo espartano»."},{"author":"Josiah Ober","title":"Mass and Elite in Democratic Athens","year":"1989","kind":"estudio","note":"Analiza cómo la retórica mediaba la relación entre élite y demos."},{"author":"Hans van Wees","title":"Greek Warfare: Myths and Realities","year":"2004","kind":"estudio","note":"Principal revisión de la tesis hoplítica."}]},{"type":"images","items":[{"src":"/img/grecia/portada.jpg","alt":"El Partenón visto desde el oeste, con las columnas dóricas de su fachada en pie","width":1200,"height":843,"role":"portada","caption":"El Partenón, construido en la Acrópolis de Atenas entre 447 y 432 a. C.","author":"Steve Swayne","title":"The Parthenon in Athens","year":"1978","source":"Wikimedia Commons","license":"CC BY 2.0","url":"https://commons.wikimedia.org/wiki/File:The_Parthenon_in_Athens.jpg"},{"src":"/img/grecia/pericles.jpg","alt":"Busto de mármol de un hombre barbado con casco corintio echado hacia atrás sobre la frente","width":1200,"height":1818,"role":"figura","section":2,"caption":"Retrato de Pericles, copia romana de un original griego. El casco lo presenta como estratego, el único cargo al que se reelegía por votación.","author":"Copy of Kresilas","title":"Pericles Pio-Clementino Inv269 n2","year":"sin fecha","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Pericles_Pio-Clementino_Inv269_n2.jpg"},{"src":"/img/grecia/ostracon.jpg","alt":"Fragmento de cerámica con un nombre griego rayado a mano sobre la superficie","width":1200,"height":1219,"role":"figura","section":2,"caption":"Ostracon con el nombre de Temístocles. Cada año la asamblea podía desterrar diez años a un ciudadano escribiendo su nombre en un cascote.","author":"Marsyas","title":"Ostracon with the name of Themistocles","year":"2005","source":"Wikimedia Commons","license":"CC BY 4.0","url":"https://commons.wikimedia.org/wiki/File:Ostracon_with_the_name_of_Themistocles.jpg"},{"src":"/img/grecia/epidauro.jpg","alt":"Teatro griego de gradas semicirculares de piedra encajadas en la ladera, con la orquestra circular en el centro","width":1200,"height":800,"role":"figura","section":5,"caption":"El teatro de Epidauro, del siglo IV a. C. Cabían unos catorce mil espectadores: el teatro era un acto cívico, no un espectáculo minoritario.","author":"Olecorre","title":"Theatre of Epidaurus OLC","year":"2007","source":"Wikimedia Commons","license":"CC BY-SA 3.0","url":"https://commons.wikimedia.org/wiki/File:Theatre_of_Epidaurus_OLC.jpg"}]},{"type":"documents","items":[{"section":2,"title":"Pericles describe la democracia ateniense","text":"Nuestro régimen se llama democracia porque el gobierno no depende de unos pocos, sino de la mayoría.\n\nEn lo que toca a los asuntos privados, la ley concede igualdad a todos; pero en cuanto a la consideración pública, cada uno es preferido no por pertenecer a una clase, sino por su mérito.\n\nY tampoco la pobreza es un obstáculo: quien puede hacer un bien a la ciudad no se ve impedido por la oscuridad de su condición.","source":"Tucídides, Historia de la guerra del Peloponeso, II, 37. Discurso fúnebre de Pericles, 431 a. C.","note":"Versión propia a partir del griego. Tucídides advierte que reconstruye los discursos, no los transcribe.","question":"Pericles dice que la pobreza no impide participar. ¿A quiénes deja fuera este retrato sin mencionarlos siquiera? Compáralo con lo que el apartado dice sobre quién era ciudadano."}]}]'::jsonb, 0, true
from public.topics where slug = 'grecia'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: guerra-fria
insert into public.lessons (topic_id, title, body, position, published)
select id, 'Guerra Fría y descolonización', '[{"type":"section","title":"De la Gran Alianza a la ruptura","text":"La coalición que derrotó a Alemania era una alianza de conveniencia entre sistemas incompatibles, y su ruptura empezó antes de que terminara la guerra. En Yalta y Potsdam se acordó lo que se podía acordar y se aplazó lo demás, sobre todo Alemania y Polonia. La cuestión polaca es la primera en romperse: los aliados occidentales pedían elecciones libres y Stalin exigía un gobierno amigo en el corredor por el que Rusia había sido invadida dos veces en treinta años.\n\nLa percepción mutua se endureció con rapidez. El telegrama largo de George Kennan desde Moscú en 1946 describió a la Unión Soviética como un poder expansivo por inseguridad histórica, al que había que contener con firmeza paciente sin necesidad de guerra. La respuesta soviética, el telegrama de Novikov, describía a Estados Unidos como una potencia que buscaba el dominio mundial aprovechando su monopolio atómico. Ninguna de las dos lecturas era absurda desde su propio punto de partida.\n\nEn 1947 la ruptura se formalizó. La doctrina Truman convirtió una ayuda concreta a Grecia y Turquía en una declaración general de apoyo a los pueblos que resistieran la subyugación; el Plan Marshall ofreció trece mil millones de dólares a Europa, con una condición de coordinación económica que la URSS entendió, con razón, como un instrumento de integración occidental, y prohibió a sus satélites participar. La respuesta fue el Kominform y la soviación acelerada de Europa oriental, con el golpe de Praga de 1948 como punto de no retorno.\n\nAlemania fue el problema y la solución. La unificación de las zonas occidentales y la reforma monetaria provocaron el bloqueo soviético de Berlín en 1948, respondido con un puente aéreo de once meses que abasteció a dos millones de personas. El resultado fue la consolidación de dos Estados alemanes en 1949 y la creación de la OTAN, la primera alianza militar en tiempo de paz de la historia de Estados Unidos. El Pacto de Varsovia llegó en 1955, tras el ingreso de la República Federal en la OTAN.\n\nEl año 1949 cambió la escala del conflicto. La Unión Soviética hizo estallar su primera bomba atómica, mucho antes de lo previsto en Washington, y los comunistas ganaron la guerra civil china. El documento NSC-68 de 1950 tradujo esa alarma en un programa de rearme masivo y en una lectura del conflicto como enfrentamiento global entre libertad y esclavitud, es decir, en un marco en el que cualquier lugar del planeta podía ser un frente.","textEso":"Estados Unidos y la URSS habían ganado la guerra juntos, pero querían cosas distintas para Europa. Stalin buscaba un cinturón de países amigos que impidieran otra invasión desde el oeste; los aliados occidentales querían democracias y economías abiertas. Entre 1945 y 1948 esa diferencia se convirtió en ruptura: la URSS impuso regímenes comunistas en Europa del este y Estados Unidos respondió con el Plan Marshall, una ayuda económica enorme para reconstruir Europa occidental.","textBachillerato":"La ruptura entre los aliados no fue instantánea sino un proceso entre 1945 y 1948, alimentado por percepciones de seguridad incompatibles. Para la URSS, que había sufrido dos invasiones desde el oeste en treinta años, un glacis de Estados controlados era una exigencia defensiva; para Estados Unidos, la sovietización de Europa del este contradecía los acuerdos de Yalta sobre elecciones libres y amenazaba la reconstrucción económica.\n\nLa secuencia es conocida: el telegrama largo de Kennan y la doctrina de la contención, la doctrina Truman de 1947, el Plan Marshall con más de trece mil millones de dólares y su rechazo obligado por los países del este, y los golpes que consolidaron regímenes comunistas, con Praga en 1948 como caso decisivo. La historiografía ha oscilado entre la tesis ortodoxa que responsabiliza a la expansión soviética, la revisionista que subraya los intereses económicos estadounidenses y una síntesis posrevisionista, hoy dominante, que describe una espiral de seguridad en la que cada medida defensiva de un bando fue leída como agresión por el otro.","callout":"Ni Washington ni Moscú planeaban una guerra en 1947. Lo que hubo fue una espiral en la que cada medida defensiva de un bando resultaba, leída desde el otro, indistinguible de una preparación ofensiva."},{"type":"section","title":"Bloques, Corea y el equilibrio del terror","text":"La guerra de Corea, entre 1950 y 1953, fue el primer choque armado a gran escala del conflicto y fijó sus reglas. Una invasión del sur por el norte, una intervención estadounidense bajo bandera de Naciones Unidas aprovechando la ausencia soviética del Consejo de Seguridad, una contraofensiva que llegó hasta la frontera china y la entrada masiva de voluntarios chinos que devolvió el frente al paralelo 38. Tres millones de muertos y ninguna frontera cambiada, pero también la lección de que la escalada podía y debía detenerse.\n\nLa carrera armamentística siguió su propia lógica. Estados Unidos probó la bomba de hidrógeno en 1952, la URSS en 1953; llegaron los bombarderos estratégicos, después los misiles balísticos intercontinentales tras el Sputnik de 1957, y finalmente los submarinos lanzamisiles, que hacían imposible destruir el arsenal enemigo en un primer golpe. De ahí salió la destrucción mutua asegurada: una situación en la que atacar equivalía a suicidarse y en la que, paradójicamente, la vulnerabilidad recíproca era el fundamento de la estabilidad.\n\nLa muerte de Stalin en 1953 abrió una etapa distinta. Jruschov denunció el culto a la personalidad en 1956 y formuló la coexistencia pacífica, es decir, la competencia sin guerra entre sistemas. Pero la misma dirección aplastó la revolución húngara ese mismo otoño, y la contradicción entre desestalinización y control del bloque marcó todo el período, hasta la Primavera de Praga de 1968 y la doctrina Brézhnev que la justificó.\n\nLa crisis de los misiles de Cuba en octubre de 1962 fue el momento en que el sistema estuvo más cerca de fallar. El despliegue soviético de misiles en la isla respondía a la inferioridad estratégica y a la defensa de un aliado amenazado tras Bahía de Cochinos; el bloqueo estadounidense y trece días de negociación al filo terminaron con la retirada de los misiles a cambio del compromiso de no invadir Cuba y de la retirada discreta de los Júpiter de Turquía. Los documentos desclasificados han mostrado que hubo incidentes que ninguno de los dos gobiernos controlaba, incluido un submarino soviético con torpedo nuclear.\n\nLa consecuencia fue una arquitectura de contención de riesgos: teléfono rojo, tratado de prohibición parcial de ensayos en 1963 y tratado de no proliferación en 1968. También la certeza, en ambas capitales, de que el enfrentamiento se libraría en otros escenarios. Y esos escenarios ya estaban apareciendo en Asia y en África.","textEso":"Europa quedó partida en dos bloques con sus alianzas militares, la OTAN y el Pacto de Varsovia, y Alemania dividida en dos Estados. El primer choque grave fue el bloqueo de Berlín en 1948, resuelto con un puente aéreo. En 1950 la guerra de Corea llevó el conflicto a Asia y dejó el país partido, como sigue hoy. Y a partir de que la URSS consiguiera la bomba atómica, las dos potencias supieron que una guerra directa las destruiría a ambas: ese miedo mutuo es lo que evitó la guerra.","textBachillerato":"La división se institucionalizó rápidamente: OTAN en 1949, Pacto de Varsovia en 1955, dos Estados alemanes desde 1949 y una frontera fortificada. El bloqueo de Berlín de 1948-1949 fue la primera crisis grave y se resolvió con un puente aéreo que abasteció a la ciudad durante once meses sin recurrir a la fuerza, un precedente importante sobre cómo se gestionarían los choques posteriores.\n\nLa guerra de Corea, entre 1950 y 1953, extendió el conflicto a Asia, causó millones de muertos y terminó en el statu quo previo, con una división que persiste. El elemento estructural es la disuasión nuclear: tras la primera prueba soviética de 1949 y el desarrollo de las armas termonucleares y de los misiles intercontinentales, se consolidó la lógica de la destrucción mutua asegurada. Es una paradoja que conviene explicar con cuidado: la existencia de armas capaces de aniquilar a ambos contendientes hizo improbable la guerra directa entre ellos y a la vez desplazó el enfrentamiento a la periferia.","callout":null},{"type":"section","title":"La descolonización","text":"En 1945 los imperios europeos gobernaban a un tercio de la humanidad; en 1975 casi no quedaba nada. La guerra había sido el acelerador: destruyó el prestigio de las metrópolis, obligó a movilizar tropas y recursos coloniales prometiendo contrapartidas, y dejó a Gran Bretaña y Francia arruinadas frente a dos superpotencias que, por motivos distintos, eran retóricamente anticoloniales.\n\nAsia fue primero. La India se independizó en 1947 tras décadas de movilización del Congreso, con una partición que produjo entre uno y dos millones de muertos y catorce millones de desplazados, y cuyo trazado apresurado sigue generando conflicto. Indonesia arrancó su independencia a los Países Bajos en 1949 tras cuatro años de guerra. Indochina se convirtió en una guerra larga: el Viet Minh derrotó a Francia en Dien Bien Phu en 1954 y la partición provisional del país abrió la puerta a la intervención estadounidense.\n\nÁfrica vivió su descolonización sobre todo entre 1957 y 1965. Ghana con Nkrumah abrió el camino en 1957 y solo en 1960 nacieron diecisiete Estados. Donde había colonos europeos instalados el proceso fue violento: la guerra de Argelia, de 1954 a 1962, costó cientos de miles de muertos, empleó la tortura como método y derribó de paso a la Cuarta República francesa; Kenia, Angola, Mozambique y Rodesia siguieron caminos igualmente sangrientos. Portugal solo abandonó sus colonias tras la revolución de 1974, provocada en buena medida por el desgaste de esas guerras.\n\nLa independencia política no resolvió la dependencia económica. Los nuevos Estados heredaron fronteras trazadas en Berlín, economías organizadas para exportar una o dos materias primas, administraciones escasas y ejércitos que pronto aprendieron a dar golpes. Kwame Nkrumah llamó neocolonialismo a esa situación: soberanía formal con decisiones económicas tomadas fuera. Frantz Fanon, desde la guerra de Argelia, escribió sobre la violencia colonial y sobre el riesgo de que una burguesía nacional sustituyera al colonizador sin cambiar la estructura.\n\nLa conferencia de Bandung de 1955 reunió a veintinueve Estados asiáticos y africanos y formuló una posición propia: anticolonialismo, soberanía, coexistencia y desarrollo. De ahí salió el Movimiento de Países No Alineados, con Nehru, Nasser, Tito, Sukarno y Nkrumah. No fue neutralidad, sino un intento de convertir la rivalidad de las superpotencias en margen de maniobra, y a menudo funcionó: Egipto financió la presa de Asuán con dinero soviético después de que Estados Unidos retirara su oferta.","textEso":"Mientras tanto los imperios coloniales se deshicieron. Las metrópolis habían quedado arruinadas por la guerra y los movimientos independentistas se habían fortalecido. La India se independizó en 1947, con una partición que provocó millones de desplazados y cientos de miles de muertos. En África, casi todo el continente se independizó entre 1957 y 1965. Hubo salidas negociadas y guerras muy duras, como las de Argelia y Vietnam contra Francia.","textBachillerato":"La descolonización se aceleró por la convergencia de tres factores: metrópolis exhaustas económica y militarmente, movimientos nacionalistas reforzados por la experiencia bélica y por la participación de tropas coloniales, y un contexto internacional en el que ambas superpotencias se declaraban anticolonialistas por razones propias.\n\nLos procesos fueron muy distintos. La independencia de la India en 1947 fue negociada, pero la partición entre India y Pakistán provocó entre diez y quince millones de desplazados y cientos de miles de muertos. En África, entre 1957 y 1965 se independizaron la mayoría de los territorios, con transiciones pactadas en el ámbito británico y francés y con guerras prolongadas en Argelia, donde el conflicto acabó derribando la Cuarta República francesa, y más tarde en las colonias portuguesas. Los nuevos Estados heredaron fronteras artificiales, economías de monocultivo y estructuras administrativas pensadas para extraer, no para gobernar.","callout":"La descolonización no fue una concesión graciosa de las metrópolis ni un simple efecto de la Guerra Fría: fue el resultado de movilizaciones anticoloniales que llevaban décadas organizándose y que aprovecharon una coyuntura internacional favorable."},{"type":"section","title":"El Tercer Mundo como campo de batalla","text":"Odd Arne Westad ha propuesto leer la Guerra Fría desde el sur y no desde Europa, y el cambio de foco es decisivo. En Europa la línea de 1945 no se movió y no hubo guerra; fuera de ella hubo intervenciones, golpes y conflictos que costaron millones de vidas. Irán en 1953, Guatemala en 1954, el Congo en 1960 con el asesinato de Lumumba, Chile en 1973: la lista de gobiernos derribados con participación de servicios de inteligencia occidentales es larga, y la lista soviética en su propia esfera también.\n\nVietnam fue el caso extremo. Estados Unidos heredó el conflicto de Francia, sostuvo un régimen survietnamita sin base social propia, escaló hasta más de medio millón de soldados y lanzó sobre Indochina más bombas que todas las de la Segunda Guerra Mundial. Perdió cincuenta y ocho mil hombres, mató a entre uno y tres millones de vietnamitas y salió derrotado en 1975. El coste interno fue enorme: fractura social, crisis de confianza en las instituciones y un límite político duradero a la intervención militar.\n\nCuba muestra la otra cara: una revolución nacional propia, alineada con Moscú después y no antes, que envió tropas a Angola y a Etiopía con una agenda internacionalista que no siempre coincidía con la soviética. La idea de que los conflictos del sur eran simples marionetas de las superpotencias no resiste el examen de los archivos: los actores locales tenían proyectos propios y con frecuencia arrastraron a sus patrocinadores más que al revés.\n\nOriente Medio combinó descolonización, conflicto árabe-israelí y petróleo. Suez en 1956 demostró que Gran Bretaña y Francia ya no podían actuar sin permiso de Washington; las guerras de 1967 y 1973 reordenaron la región y produjeron la crisis del petróleo, que multiplicó por cuatro el precio del crudo y terminó con el largo crecimiento de posguerra en Occidente. La revolución iraní de 1979 introdujo un actor que no encajaba en ninguno de los dos bloques.\n\nChina merece capítulo aparte porque rompió la bipolaridad. La ruptura chino-soviética, consumada hacia 1960 por diferencias ideológicas, de liderazgo y de frontera, llegó a producir choques armados en 1969. Y abrió la puerta al viaje de Nixon a Pekín en 1972, una de las maniobras diplomáticas más consecuentes del siglo, que convirtió un conflicto de dos en un triángulo y presionó a Moscú por dos flancos.","textEso":"Las dos superpotencias evitaron enfrentarse directamente, pero convirtieron el resto del mundo en su campo de batalla. Apoyaron golpes de Estado, financiaron guerrillas y sostuvieron dictaduras con tal de que estuvieran en su bando: Corea, Vietnam, Angola, Afganistán, y en América Latina toda una serie de intervenciones y dictaduras militares. La crisis de los misiles de Cuba, en 1962, fue el momento en que el mundo estuvo más cerca de una guerra nuclear.","textBachillerato":"La imposibilidad del choque directo trasladó la confrontación al llamado Tercer Mundo, donde los conflictos locales se leyeron en clave bipolar. Estados Unidos respaldó golpes y dictaduras allí donde temía influencia soviética —Irán en 1953, Guatemala en 1954, Chile en 1973— y la URSS sostuvo regímenes y guerrillas afines.\n\nVietnam es el caso más costoso: una guerra de independencia frente a Francia convertida en enfrentamiento de bloques, con más de un millón y medio de muertos y la primera derrota militar estadounidense, con enormes consecuencias internas. Afganistán, desde 1979, produjo un desgaste comparable para la URSS. La crisis de los misiles de Cuba de octubre de 1962 fue el momento de mayor riesgo nuclear: documentación posterior ha mostrado que el peligro fue mayor de lo que se creyó, con armas tácticas ya desplegadas en la isla. También surgió una tercera vía, el Movimiento de Países No Alineados, con capacidad de presión limitada pero significativa en foros internacionales.","callout":null},{"type":"section","title":"Distensión y Segunda Guerra Fría","text":"La distensión de los años setenta fue un intento de administrar la rivalidad en vez de eliminarla. Incluyó los acuerdos SALT sobre armas estratégicas, el reconocimiento mutuo de las dos Alemanias impulsado por la Ostpolitik de Brandt, y el Acta Final de Helsinki de 1975, que consagró las fronteras europeas a cambio de un capítulo sobre derechos humanos que Moscú firmó pensando que era retórico.\n\nEse capítulo tuvo consecuencias imprevistas. Grupos como la Carta 77 checoslovaca o los comités de Helsinki en la URSS usaron un texto firmado por sus propios gobiernos para exigir su cumplimiento, lo que dio a la disidencia una base legal y una visibilidad internacional que no tenía antes. Solidaridad en Polonia, con diez millones de afiliados en 1980, mostró lo que podía crecer en esa grieta, aunque fuese aplastada por la ley marcial en 1981.\n\nLa distensión se rompió a finales de la década. La invasión soviética de Afganistán en diciembre de 1979 inauguró una guerra de diez años que acabó siendo el Vietnam soviético, con una insurgencia financiada por Estados Unidos, Arabia Saudí y Pakistán. Reagan aumentó el gasto militar, lanzó la Iniciativa de Defensa Estratégica y elevó el tono; el despliegue de euromisiles provocó las mayores manifestaciones pacifistas de la historia europea. En 1983 hubo al menos dos incidentes que estuvieron cerca de producir una respuesta nuclear por error.\n\nLa economía soviética llevaba desde los años setenta en desaceleración estructural: un sistema de planificación incapaz de asimilar la revolución informática, una agricultura deficitaria, un gasto militar que absorbía una parte desproporcionada del producto y una dependencia creciente de la exportación de crudo, cuyo precio se hundió en 1986. Nada de esto obligaba por sí solo a un cambio de régimen, pero cerraba la posibilidad de seguir igual.\n\nMijaíl Gorbachov llegó en 1985 con la intención de salvar el socialismo reformándolo. La perestroika buscó reestructurar la economía, la glásnost abrió la discusión pública y el nuevo pensamiento en política exterior renunció a la doctrina Brézhnev. En 1987 firmó con Reagan el tratado INF, que eliminó una categoría entera de misiles; en 1989 retiró las tropas de Afganistán y dejó claro a los gobiernos de Europa oriental que no habría tanques soviéticos para sostenerlos.","textEso":"En los años setenta hubo un periodo de distensión: acuerdos para limitar las armas nucleares, reconocimiento de las fronteras europeas y más contacto entre bloques. Terminó al final de la década, con la invasión soviética de Afganistán y la llegada de Reagan, que reactivó la carrera armamentística. La URSS entró en una crisis profunda: su economía no podía sostener a la vez el gasto militar y el nivel de vida de su población.","textBachillerato":"La distensión de los años setenta produjo resultados concretos: acuerdos SALT de limitación de armas estratégicas, tratado de no proliferación, Ostpolitik alemana y el Acta Final de Helsinki de 1975, que reconoció las fronteras europeas a cambio de compromisos en derechos humanos. Ese tercer cesto fue aprovechado por disidentes del este y resultó, a medio plazo, más corrosivo de lo previsto.\n\nLa distensión terminó con la invasión soviética de Afganistán en 1979 y con el giro de Reagan, que combinó incremento del gasto militar, retórica de confrontación y programas como la Iniciativa de Defensa Estratégica. La URSS afrontaba mientras tanto un estancamiento económico profundo: crecimiento decreciente, agricultura ineficiente, dependencia de la exportación de hidrocarburos cuyo precio se hundió en los ochenta y un gasto militar que absorbía una proporción del producto muy superior a la estadounidense. El sistema podía sostener el imperio o el nivel de vida, pero no ambos.","callout":"El capítulo de derechos humanos de Helsinki, que Moscú consideró un precio menor, se convirtió en el instrumento legal con el que la disidencia del Este exigió cuentas a sus propios gobiernos."},{"type":"section","title":"1989, 1991 y el balance","text":"El año 1989 fue una cadena de acontecimientos en pocos meses: elecciones semilibres en Polonia con victoria de Solidaridad, apertura de la frontera húngara, manifestaciones masivas en Leipzig y Praga, caída del Muro de Berlín el 9 de noviembre por una combinación de presión popular y confusión administrativa, y ejecución de Ceaucescu en diciembre. Lo excepcional no fue la caída de los regímenes sino que ocurriera casi sin sangre, y eso dependió de una decisión previa: la de no intervenir.\n\nLa Unión Soviética se disolvió dos años después por un camino distinto. Las reformas liberaron fuerzas centrífugas en las repúblicas bálticas, en el Cáucaso y sobre todo en Rusia, donde Yeltsin usó la soberanía rusa como palanca contra el centro. El golpe de agosto de 1991 de un sector del aparato fracasó en tres días y liquidó lo que quedaba de autoridad del partido y del propio Gorbachov. En diciembre, los dirigentes de Rusia, Ucrania y Bielorrusia disolvieron la URSS.\n\nPor qué se hundió es una discusión abierta. Una posición atribuye el desenlace a la presión estadounidense y al gasto militar que la URSS no podía igualar. Otra subraya el agotamiento estructural del modelo desde los años setenta. Una tercera, defendida entre otros por Stephen Kotkin y Archie Brown, señala la agencia de Gorbachov: fue su decisión de no usar la fuerza lo que convirtió una crisis en una disolución pacífica, y sin ella el desenlace habría sido muy distinto.\n\nLa descolonización dejó un balance igual de complejo. Se acabó con la dominación formal y nació un sistema internacional con más de ciento cincuenta Estados; también quedaron fronteras artificiales, economías dependientes, guerras civiles alimentadas desde fuera y una deuda que condicionó el desarrollo. Los estudios poscoloniales, desde Edward Said, han insistido además en la persistencia de estructuras culturales y de conocimiento que sobrevivieron a la retirada de las banderas.\n\nLa Guerra Fría dejó como legado la proliferación nuclear, una red de alianzas que sigue vigente, un continente europeo dividido que tardó décadas en recomponerse y la instalación duradera de la idea de que el orden internacional se decide entre pocos. Que cuarenta y cinco años de enfrentamiento entre potencias nucleares terminaran sin un disparo entre ellas es un resultado que ninguna teoría anticipaba y que sigue exigiendo explicación.","textEso":"El final llegó muy rápido. Gorbachov intentó reformar el sistema y renunció a intervenir militarmente en Europa del este; sin ese apoyo, los regímenes cayeron uno tras otro en 1989, y el Muro de Berlín se abrió en noviembre. En 1991 la propia URSS se disolvió. El desenlace se ha explicado de muchas formas, pero hay un dato claro: fue un proceso mayoritariamente pacífico, algo excepcional en el desmantelamiento de un imperio.","textBachillerato":"Gorbachov intentó reformar el sistema con la perestroika y la glásnost, y adoptó una decisión de consecuencias decisivas: renunciar a la doctrina Brézhnev, es decir, a intervenir militarmente para sostener a los regímenes aliados. Sin esa garantía, los gobiernos de Europa del este cayeron en cadena durante 1989, en su mayoría sin violencia, con la excepción rumana. La apertura del Muro de Berlín en noviembre fue el símbolo del proceso.\n\nLa URSS se disolvió formalmente en diciembre de 1991 tras el fracaso del golpe de agosto y la deriva centrífuga de las repúblicas. Las explicaciones del desenlace se reparten entre el agotamiento económico estructural, la presión exterior estadounidense, el papel personal de Gorbachov y la fuerza de los nacionalismos internos, y hoy se tiende a combinarlas. Un rasgo llamativo es que el desmantelamiento de un imperio nuclear se produjo de forma mayoritariamente pacífica. Sus consecuencias fueron enormes: crisis social profunda en el espacio postsoviético, guerras en los Balcanes y una lectura triunfalista en Occidente, la del fin de la historia, que los acontecimientos posteriores desmintieron.","callout":null},{"type":"concepts","items":[{"term":"Contención","definition":"Estrategia formulada por Kennan en 1946: frenar con firmeza paciente la expansión soviética sin buscar la guerra, esperando la transformación interna del adversario."},{"term":"Doctrina Truman","definition":"Declaración de 1947 de apoyo estadounidense a los pueblos que resistan la subyugación. Convierte una ayuda concreta en un compromiso global."},{"term":"Plan Marshall","definition":"Programa de ayuda económica a Europa desde 1948, condicionado a la coordinación entre receptores. La URSS lo entendió como integración occidental y lo vetó a sus satélites."},{"term":"Destrucción mutua asegurada","definition":"Situación en la que ambos bandos conservan capacidad de represalia tras un primer golpe, de modo que atacar equivale a suicidarse."},{"term":"Coexistencia pacífica","definition":"Doctrina formulada por Jruschov en 1956: competencia entre sistemas sin guerra directa, compatible con el control armado del propio bloque."},{"term":"Doctrina Brézhnev","definition":"Justificación de la intervención en cualquier país socialista donde el socialismo estuviera amenazado. Formulada tras la Primavera de Praga de 1968."},{"term":"Guerra por delegación","definition":"Conflicto entre terceros armados y financiados por las superpotencias, que evita el choque directo entre ellas y traslada el coste al escenario local."},{"term":"Bandung","definition":"Conferencia de 1955 de veintinueve Estados asiáticos y africanos. Origen del Movimiento de Países No Alineados y de una agenda propia del sur."},{"term":"No Alineamiento","definition":"Posición de no integrarse en ninguno de los dos bloques. No fue neutralidad pasiva sino una forma de negociar margen frente a ambos."},{"term":"Neocolonialismo","definition":"Término de Nkrumah para la soberanía formal acompañada de dependencia económica y de decisiones tomadas fuera del país."},{"term":"Distensión","definition":"Fase de los años setenta en la que la rivalidad se administra mediante acuerdos de control de armas y reconocimiento mutuo del statu quo europeo."},{"term":"Acta de Helsinki","definition":"Acuerdo de 1975 que consagró las fronteras europeas e incluyó un capítulo de derechos humanos que la disidencia del Este utilizó como base legal."},{"term":"Perestroika","definition":"Reestructuración económica y política emprendida por Gorbachov desde 1985 para reformar el sistema soviético sin abandonarlo."},{"term":"Glásnost","definition":"Apertura informativa que permitió discutir públicamente la historia y los problemas del país. Erosionó la legitimidad del sistema más rápido de lo previsto."}]},{"type":"debates","items":[{"question":"¿Quién provocó la Guerra Fría?","positions":[{"school":"Ortodoxa (historiografía estadounidense de los años cincuenta)","argument":"La expansión soviética sobre Europa oriental, la imposición de regímenes satélites y el golpe de Praga obligaron a Occidente a una respuesta defensiva que no había buscado."},{"school":"Revisionista (Williams, 1959; Kolko)","argument":"Estados Unidos necesitaba mercados abiertos y estabilidad capitalista global. El Plan Marshall y el monopolio atómico fueron instrumentos de una expansión económica que Moscú percibió correctamente como amenaza."},{"school":"Postrevisionista y de archivos (Gaddis; Leffler; Zubok y Pleshakov)","argument":"Hubo una espiral de percepciones en la que cada medida defensiva resultaba indistinguible de una ofensiva. Los archivos soviéticos muestran a un Stalin cauteloso y a la vez decidido a asegurar una esfera de seguridad."}],"state":"La apertura de archivos ha desplazado la pregunta de la culpa a la de los mecanismos: cómo dos potencias sin plan de guerra construyeron un enfrentamiento de cuarenta y cinco años."},{"question":"¿Qué explica el fin de los imperios coloniales?","positions":[{"school":"Presión desde abajo","argument":"Los movimientos anticoloniales llevaban décadas organizándose, movilizaron a millones de personas y elevaron el coste de la dominación hasta hacerla inviable. La independencia se arrancó, no se concedió."},{"school":"Cálculo metropolitano (Darwin; Louis y Robinson)","argument":"Las metrópolis, arruinadas y presionadas por Washington, decidieron que el imperio formal ya no compensaba y buscaron conservar la influencia económica traspasando el coste administrativo."},{"school":"Coyuntura internacional (Westad, 2005)","argument":"La Guerra Fría creó un espacio en el que los movimientos anticoloniales encontraron patrocinadores, foros y legitimidad, y a la vez convirtió sus países en escenarios de una disputa ajena."}],"state":"Predomina una explicación combinada que atiende a la iniciativa anticolonial sin ignorar el contexto internacional, y que estudia cada caso por separado en vez de buscar un patrón único."},{"question":"¿Por qué se hundió la Unión Soviética?","positions":[{"school":"Victoria de la presión occidental","argument":"El rearme de los años ochenta y la Iniciativa de Defensa Estratégica impusieron a Moscú una carrera que su economía no podía sostener, y la obligaron a reformas que descontrolaron el sistema."},{"school":"Agotamiento estructural","argument":"El modelo llevaba desde los años setenta en desaceleración: planificación incapaz de asimilar la informática, agricultura deficitaria y dependencia del precio del crudo, que se hundió en 1986."},{"school":"Agencia de Gorbachov (Brown, 1996; Kotkin, 2001)","argument":"La crisis no imponía el desenlace. Fue la decisión de reformar y de no usar la fuerza, en el bloque y en el propio país, la que convirtió un declive en una disolución pacífica."}],"state":"La historiografía tiende a combinar el declive estructural con la contingencia de las decisiones de 1985 a 1991, y a rechazar tanto el determinismo económico como el relato de una victoria planificada."}]},{"type":"timeline","items":[{"date":"Febrero de 1945","event":"Conferencia de Yalta: acuerdos sobre la posguerra, Polonia y la entrada soviética en la guerra del Pacífico."},{"date":"Marzo de 1947","event":"Doctrina Truman: ayuda a Grecia y Turquía y formulación pública de la contención."},{"date":"1947–1948","event":"Plan Marshall, independencia y partición de la India, y golpe comunista en Checoslovaquia."},{"date":"1948–1949","event":"Bloqueo y puente aéreo de Berlín, creación de la OTAN y primera bomba atómica soviética."},{"date":"1949","event":"Victoria comunista en China y proclamación de la República Popular."},{"date":"1950–1953","event":"Guerra de Corea: primer choque armado a gran escala entre los bloques, sin enfrentamiento directo entre las superpotencias."},{"date":"Abril de 1955","event":"Conferencia de Bandung: veintinueve Estados asiáticos y africanos formulan una posición propia."},{"date":"1956","event":"Discurso secreto de Jruschov, crisis de Suez y aplastamiento de la revolución húngara."},{"date":"Octubre de 1962","event":"Crisis de los misiles de Cuba: trece días al borde de la guerra nuclear."},{"date":"1960–1965","event":"Independencia de la mayor parte de África subsahariana. Solo en 1960 nacen diecisiete Estados."},{"date":"1975","event":"Fin de la guerra de Vietnam, revolución de los claveles y Acta Final de Helsinki."},{"date":"1985–1989","event":"Gorbachov: perestroika, glásnost, retirada de Afganistán y renuncia a la doctrina Brézhnev."},{"date":"1989–1991","event":"Caída del Muro, revoluciones en Europa del Este y disolución de la Unión Soviética."}]},{"type":"sources","items":[{"author":"George Kennan","title":"Telegrama largo y artículo Las fuentes de la conducta soviética","year":"1946–1947","kind":"primaria","note":"Formulación original de la contención por el diplomático que después criticó su militarización."},{"author":"Winston Churchill","title":"Discurso del telón de acero en Fulton","year":"1946","kind":"primaria","note":"Fija en el lenguaje público la imagen de una Europa dividida en dos."},{"author":"Harry Truman","title":"Mensaje al Congreso sobre Grecia y Turquía","year":"1947","kind":"primaria","note":"Texto fundacional de la doctrina Truman y de la lectura global del conflicto."},{"author":"Consejo de Seguridad Nacional de Estados Unidos","title":"NSC-68","year":"1950","kind":"primaria","note":"Documento interno que propone el rearme masivo y define el conflicto en términos morales absolutos."},{"author":"Conferencia Asiático-Africana","title":"Comunicado final de Bandung","year":"1955","kind":"primaria","note":"Diez principios de coexistencia y anticolonialismo formulados por los propios países del sur."},{"author":"Nikita Jruschov","title":"Discurso secreto ante el XX Congreso","year":"1956","kind":"primaria","note":"Denuncia del culto a la personalidad. Abrió la desestalinización y desestabilizó al bloque."},{"author":"Frantz Fanon","title":"Los condenados de la tierra","year":"1961","kind":"primaria","note":"Análisis de la violencia colonial y advertencia sobre una burguesía nacional que sustituya al colonizador sin cambiar la estructura."},{"author":"Kwame Nkrumah","title":"Neocolonialismo, última etapa del imperialismo","year":"1965","kind":"primaria","note":"Formula el concepto de soberanía formal con dependencia económica real."},{"author":"Conferencia sobre Seguridad y Cooperación en Europa","title":"Acta Final de Helsinki","year":"1975","kind":"primaria","note":"Fronteras a cambio de derechos humanos. Su tercera cesta se convirtió en herramienta de la disidencia."},{"author":"Václav Havel","title":"El poder de los sin poder","year":"1978","kind":"primaria","note":"Ensayo sobre la vida en la mentira bajo el socialismo real y sobre la resistencia cotidiana."},{"author":"Mijaíl Gorbachov","title":"Perestroika","year":"1987","kind":"primaria","note":"Exposición del programa reformista por su autor, con la intención declarada de salvar el socialismo."},{"author":"William Appleman Williams","title":"La tragedia de la diplomacia norteamericana","year":"1959","kind":"estudio","note":"Origen de la corriente revisionista sobre el papel económico de Estados Unidos en el conflicto."},{"author":"Edward Said","title":"Orientalismo","year":"1978","kind":"estudio","note":"Analiza cómo el saber sobre Oriente construyó y sostuvo la dominación. Base de los estudios poscoloniales."},{"author":"John Lewis Gaddis","title":"Estados Unidos y los orígenes de la Guerra Fría","year":"1972","kind":"estudio","note":"Síntesis postrevisionista sobre las percepciones mutuas y la dinámica de la espiral."},{"author":"Melvyn Leffler","title":"A Preponderance of Power","year":"1992","kind":"estudio","note":"Estudio de la seguridad nacional estadounidense que reconstruye las decisiones sin atribuirlas a una sola causa."},{"author":"Archie Brown","title":"El factor Gorbachov","year":"1996","kind":"estudio","note":"Defiende el peso decisivo de las decisiones del último dirigente soviético en el desenlace pacífico."},{"author":"Vladislav Zubok y Constantine Pleshakov","title":"Inside the Kremlins Cold War","year":"1996","kind":"estudio","note":"Reconstrucción de la política soviética con archivos abiertos, desde Stalin hasta Jruschov."},{"author":"Stephen Kotkin","title":"Armageddon Averted","year":"2001","kind":"estudio","note":"Explica la disolución soviética como un colapso institucional relativamente ordenado y no como una revolución."},{"author":"Odd Arne Westad","title":"La Guerra Fría global","year":"2005","kind":"estudio","note":"Desplaza el centro del relato al Tercer Mundo, donde el conflicto costó millones de vidas."},{"author":"Tony Judt","title":"Postguerra","year":"2005","kind":"estudio","note":"Historia de Europa desde 1945 que integra las dos mitades del continente en un solo relato."},{"author":"Frederick Cooper","title":"Africa since 1940","year":"2002","kind":"estudio","note":"Descolonización africana desde las sociedades africanas, no desde las metrópolis."},{"author":"Eric Hobsbawm","title":"Historia del siglo XX","year":"1994","kind":"estudio","note":"Síntesis del siglo corto con la Guerra Fría y la descolonización tratadas como procesos del mismo período."}]},{"type":"images","items":[{"src":"/img/guerra-fria/portada.jpg","alt":"Obreros levantando un muro de bloques de hormigón en una calle de Berlín, vigilados por soldados","width":1200,"height":832,"role":"portada","caption":"Construcción del Muro de Berlín, noviembre de 1961.","author":"National Archives","title":"Berlin Wall 1961-11-20","year":"1961","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Berlin_Wall_1961-11-20.jpg"},{"src":"/img/guerra-fria/caida-muro.jpg","alt":"Personas subidas al Muro de Berlín ante la Puerta de Brandeburgo, rodeadas de multitud","width":1200,"height":904,"role":"figura","section":5,"caption":"El Muro de Berlín la noche del 9 de noviembre de 1989.","author":"Unknown photographer, Reproduction by Lear 21 at English Wikipedia .","title":"West and East Germans at the Brandenburg Gate in 1989","year":"1989","source":"Wikimedia Commons","license":"CC BY-SA 3.0","url":"https://commons.wikimedia.org/wiki/File:Thefalloftheberlinwall1989.JPG"},{"src":"/img/guerra-fria/puente-aereo.jpg","alt":"Fotografía de un hidroavión cuatrimotor amarrado en un lago con la ciudad al fondo","width":1200,"height":791,"role":"figura","section":1,"caption":"Puente aéreo de Berlín, 1948. Durante once meses se abasteció por aire a dos millones de personas antes que forzar el bloqueo por tierra.","author":"RAF official photographer","title":"Sunderland 201 Sqn on Havel during Berlin Airlift 1948","year":"1948","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Sunderland_201_Sqn_on_Havel_during_Berlin_Airlift_1948.jpg"},{"src":"/img/guerra-fria/gandhi.jpg","alt":"Fotografía de un hombre delgado con dhoti caminando junto a la orilla acompañado por una multitud","width":1200,"height":1710,"role":"figura","section":2,"caption":"Gandhi en Dandi al final de la Marcha de la Sal, abril de 1930. Recoger sal del mar violaba el monopolio fiscal británico: desobediencia civil calculada para ser fotografiada.","author":"Unknown author Unknown author","title":"Gandhi at Dandi, 5 April 1930","year":"1930","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Gandhi_at_Dandi%2C_5_April_1930.jpg"},{"src":"/img/guerra-fria/misiles-cuba.jpg","alt":"Fotografía aérea de reconocimiento en blanco y negro con vehículos y estructuras alargadas señaladas con rótulos","width":1200,"height":945,"role":"figura","section":3,"caption":"Fotografía de reconocimiento sobre Cuba, octubre de 1962. Trece días en los que la disuasión nuclear estuvo más cerca de fallar que nunca.","author":"Autor desconocido","title":"Cuban missiles alt","year":"sin fecha","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Cuban_missiles_alt.jpg"}]},{"type":"documents","items":[{"section":0,"title":"Churchill nombra el telón de acero","text":"Desde Stettin, en el Báltico, hasta Trieste, en el Adriático, ha caído sobre el continente un telón de acero.\n\nDetrás de esa línea se encuentran todas las capitales de los antiguos Estados de Europa central y oriental. Varsovia, Berlín, Praga, Viena, Budapest, Belgrado, Bucarest y Sofía.\n\nNo creo que la Rusia soviética desee la guerra. Lo que desea son los frutos de la guerra y la expansión indefinida de su poder y de sus doctrinas.","source":"Winston Churchill, discurso en Fulton, Misuri, 5 de marzo de 1946.","note":"Versión propia a partir del inglés. Churchill ya no era primer ministro cuando lo pronunció.","question":"El discurso es de 1946, antes de la doctrina Truman y del Plan Marshall. ¿Describe una situación o ayuda a crearla? Piensa en cómo pudo leerse en Moscú."}]}]'::jsonb, 0, true
from public.topics where slug = 'guerra-fria'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: helenismo
insert into public.lessons (topic_id, title, body, position, published)
select id, 'Alejandro y el mundo helenístico', '[{"type":"section","title":"Filipo antes que Alejandro","text":"Macedonia era en 360 a. C. un reino periférico, inestable y amenazado por ilirios y peonios, al que los griegos del sur consideraban medio bárbaro. En veinticinco años Filipo II lo convirtió en la primera potencia del Egeo, y lo hizo con un instrumento militar nuevo. La falange macedonia sustituyó la lanza hoplita por la sarisa, una pica de cinco a seis metros que exigía las dos manos y un escudo menor: menos maniobrable pero mucho más profunda y capaz de fijar al enemigo. Su función era retener, no vencer; la decisión la daba la caballería de los *hetairoi*, la caballería de los compañeros, cargando sobre el punto débil que la falange había abierto.\n\nFilipo añadió ingeniería de asedio permanente, tropas ligeras, entrenamiento continuo durante todo el año y una cadena de mando estable. Lo financiaron las minas de oro del Pangeo, que le rindieron según Diodoro unos mil talentos anuales, y lo consolidaron el matrimonio como instrumento diplomático y la corrupción sistemática de las élites griegas: la frase que Plutarco le atribuye sobre que ninguna muralla resiste a un asno cargado de oro describe bien su método.\n\nQueronea, en 338, liquidó la resistencia de Atenas y Tebas. Al año siguiente la Liga de Corinto agrupó a las ciudades griegas bajo hegemonía macedonia, con una paz general, prohibición de cambiar los regímenes existentes y una guerra panhelénica de venganza contra Persia ya declarada. Cuando Filipo fue asesinado en 336, el ejército, el plan de campaña y hasta la avanzadilla en Asia Menor estaban en su sitio.\n\nEsto no reduce a Alejandro, pero cambia la pregunta. La historiografía del siglo XIX, y buena parte de la divulgación posterior, atribuyó al hijo un genio fundador que corresponde en gran medida al padre. Los estudios de las últimas décadas han restituido a Filipo su papel, y con él una idea menos heroica del proceso: la conquista de Persia fue posible porque un Estado pequeño se había militarizado durante una generación entera.\n\nQueda un problema de fondo que la propia Antigüedad discutía: si los macedonios eran griegos. Hablaban una lengua o dialecto que los griegos del sur no entendían sin más, participaban en los Juegos Olímpicos por decisión de los jueces y eran llamados bárbaros en los discursos de Demóstenes. La cuestión sigue politizada en el presente, y por eso conviene formularla con cuidado: la identidad antigua era gradual y negociable, no una etiqueta binaria.","textEso":"Antes de Alejandro está su padre, Filipo II de Macedonia, y sin él no se entiende nada. Filipo convirtió un reino periférico y poco respetado en la primera potencia militar de Grecia: profesionalizó el ejército, alargó las lanzas de la infantería hasta los cinco metros creando la falange macedonia, combinó infantería y caballería y financió todo con las minas de oro que conquistó. En 338 a. C. derrotó a Atenas y Tebas y sometió Grecia. Cuando lo asesinaron en 336 a. C., la máquina de guerra ya estaba construida.","textBachillerato":"Macedonia era, a ojos de los griegos del sur, un reino marginal de lengua dudosa. Filipo II lo transformó en la potencia hegemónica en poco más de veinte años, y su obra es la condición de posibilidad de todo lo que vino después.\n\nSus reformas fueron a la vez militares y económicas. Creó un ejército permanente y pagado, dotó a la infantería de la sarisa, una pica de cinco a seis metros que convertía la falange en un muro inabordable de frente, y la combinó con caballería de choque en el papel decisivo. Financió el conjunto con las minas de Pangeo. A ello sumó diplomacia, sobornos y matrimonios políticos. La victoria de Queronea en 338 a. C. y la Liga de Corinto dejaron Grecia bajo control macedonio. Alejandro heredó en 336 a. C. un instrumento ya construido, y eso no resta mérito a lo que hizo con él, pero sitúa el relato.","callout":"La falange de sarisas no ganaba las batallas: las fijaba. El golpe decisivo lo daba la caballería de los compañeros. Es un sistema de armas combinadas, y su autor fue Filipo, no Alejandro."},{"type":"section","title":"Alejandro: la campaña y el problema de las fuentes","text":"La campaña ocupó once años. Gránico (334) abrió Asia Menor; Issos (333) rompió el ejército de Darío III en Cilicia; el asedio de Tiro (332) duró siete meses y terminó con una matanza y la venta como esclavos de los supervivientes; Egipto recibió al conquistador sin resistencia y allí se fundó Alejandría; Gaugamela (331) decidió la guerra. Persépolis fue saqueada e incendiada en 330. Después vinieron tres años durísimos en Bactriana y Sogdiana contra una resistencia local que no combatía en batallas campales, la campaña de la India y la victoria sobre Poro en el Hidaspes (326), hasta que el ejército se negó a avanzar más allá del Hífasis. El regreso por el desierto de Gedrosia costó, según las fuentes, más vidas que ninguna batalla. Alejandro murió en Babilonia en junio de 323, a los treinta y dos años.\n\nEl problema es cómo sabemos todo esto. No se conserva ni un solo relato contemporáneo. Calístenes, el cronista oficial de la expedición, fue ejecutado y su obra se perdió; también se perdieron las memorias de Ptolomeo, Aristóbulo, Nearco y Onesícrito. Lo que leemos son cinco autores muy posteriores: Diodoro (siglo I a. C.), Curcio Rufo y Plutarco (siglo I y comienzos del II d. C.), Arriano (siglo II d. C.) y el resumen de Justino. Es decir, entre trescientos y quinientos años después, con agendas propias y con el material ya filtrado por la propaganda de la corte y por la tradición novelesca.\n\nArriano se considera el más fiable porque declara seguir a Ptolomeo y Aristóbulo, dos participantes; pero Ptolomeo escribía como rey de Egipto, con interés directo en su propio papel. Los demás forman la llamada vulgata, más dada a lo dramático y lo prodigioso. Cualquier afirmación sobre las intenciones o el carácter de Alejandro descansa sobre este material, y conviene decirlo antes que la afirmación.\n\nSobre esa base se libró el debate historiográfico decisivo. William Tarn presentó en 1948 a un Alejandro visionario, portador de una idea de hermandad de la humanidad y de fusión entre vencedores y vencidos, apoyándose en las bodas de Susa, en la incorporación de persas al ejército y en la oración de Opis. Ernst Badian desmontó esa lectura en 1958 y en trabajos posteriores: las medidas de integración se explican por necesidad de gobernar un imperio inmenso con pocos macedonios, y el registro incluye la ejecución de Filotas y el asesinato de su padre Parmenión, la muerte de Clito a manos del propio rey en un banquete, la eliminación de Calístenes tras el conflicto por la *proskynesis* y matanzas de población civil en Tiro, Gaza, Masaga y el valle del Cofén.\n\nLa posición dominante hoy, formulada sobre todo por A. B. Bosworth, describe a un gobernante extraordinariamente capaz y extraordinariamente violento, cuya política de integración fue pragmática y cuyo proyecto último no puede reconstruirse porque las fuentes no permiten llegar hasta ahí. El Alejandro de la cultura popular —unificador de pueblos, cosmopolita avant la lettre— procede en línea directa de Droysen y de Tarn, no de los documentos.","textEso":"Alejandro tenía veinte años al heredar. En once campañas derrotó al Imperio persa, el más grande del mundo, y llegó hasta el río Indo. Fundó decenas de ciudades, muchas llamadas Alejandría. Murió en Babilonia en 323 a. C., a los treinta y dos años, sin dejar heredero capaz. Sus generales se repartieron el imperio a la fuerza y de ahí salieron tres grandes reinos: el de los Ptolomeos en Egipto, el de los Seléucidas en Asia y el de Macedonia.","textBachillerato":"La campaña de Alejandro es excepcional por su escala y su velocidad: entre 334 y 325 a. C. derrota al Imperio aqueménida en Gránico, Issos y Gaugamela, toma Egipto y Babilonia, alcanza Asia Central y el Indo, y funda una red de ciudades que articularán el comercio durante siglos. Muere en Babilonia en 323 a. C. sin sucesión viable.\n\nEl problema serio es cómo lo sabemos. No se conserva ninguna fuente contemporánea: los relatos que tenemos —Arriano, Plutarco, Diodoro, Curcio Rufo— se escribieron entre tres y cinco siglos después, a partir de memorias perdidas de sus propios oficiales. Eso significa que cada episodio llega ya interpretado, y explica por qué las lecturas oscilan entre el visionario que quería unir Oriente y Occidente y el conquistador brutal que arrasó Tebas y Persépolis. Los hechos militares son sólidos; las intenciones, mucho menos.","callout":"No existe ninguna fuente contemporánea sobre Alejandro. Todo lo que sabemos procede de autores que escriben entre tres y cinco siglos después, a partir de memorias perdidas de participantes interesados."},{"type":"section","title":"Los reinos: cómo se gobernaba una monarquía de conquista","text":"Alejandro murió sin sucesor viable y con un imperio que solo su persona mantenía unido. Siguieron cuarenta años de guerras entre sus generales, los diádocos. Ipsos (301) acabó con Antígono Monoftalmos y con la última posibilidad de reunificación; Curupedio (281) fijó el mapa. Quedaron tres grandes monarquías —la Ptolemaica en Egipto, la Seléucida en Asia y la Antigónida en Macedonia— y una periferia de reinos menores: Pérgamo de los Atálidas, el reino grecobactriano y, más al este, los reinos indogriegos.\n\nLa realeza helenística no se legitimaba por sangre ni por institución, sino por victoria. La tierra era *doríktetos chóra*, tierra conquistada con la lanza, y una definición antigua recogida en la Suda dice que la basileia no la dan la naturaleza ni el derecho, sino la capacidad de mandar un ejército y administrar los asuntos. De ahí la necesidad permanente de victorias, la centralidad de la corte y de los amigos del rey por encima de cualquier órgano representativo, y la difusión del culto al soberano: Ptolomeo I como Sóter, los honores divinos votados por Atenas a Antígono y Demetrio en 307, las dinastías divinizadas en vida.\n\nEl sostén militar y social eran los colonos grecomacedonios instalados en lotes de tierra a cambio de servicio, los cleruquías en Egipto y las *katoikíai* seléucidas, y una red de fundaciones urbanas —Antioquía, Seleucia del Tigris, Ai Khanum en el actual Afganistán— que servían a la vez de guarnición, de centro fiscal y de referencia cultural.\n\nEl Egipto ptolemaico es el caso mejor documentado del mundo antiguo, porque el clima conservó los papiros. El archivo de Zenón, administrador de una gran finca en el Fayum hacia mediados del siglo III a. C., reúne miles de documentos de gestión: contratos, cuentas, cartas, quejas de campesinos. Lo que muestran es una maquinaria fiscal de extraordinaria densidad —monopolios reales del aceite y de otros productos, banca estatal, catastro, control de la circulación— superpuesta a una estructura agraria y sacerdotal egipcia que siguió funcionando como antes.\n\nEl reino seléucida, mucho más extenso y heterogéneo, funcionó de otra manera: menos control directo y más pacto con las ciudades griegas, los templos babilonios, las dinastías locales de Anatolia y las satrapías orientales. La historiografía lo trató durante décadas como un imperio fracasado y en descomposición permanente, en buena parte porque se leía a través de fuentes griegas y romanas hostiles. Los trabajos de Susan Sherwin-White y Amélie Kuhrt, apoyados en documentación cuneiforme, lo han reevaluado como un Estado que gobernó Mesopotamia con instrumentos aqueménidas y babilonios y que duró dos siglos y medio.","textEso":"Gobernar un imperio conquistado plantea un problema práctico: son millones de personas que no hablan tu lengua ni adoran a tus dioses. La solución fue pragmática. Los reyes mantuvieron la administración que ya existía y a buena parte de sus funcionarios, cobraron los mismos impuestos y respetaron los cultos locales; los Ptolomeos incluso se hicieron representar como faraones. Lo griego quedó arriba: la corte, el ejército y la élite urbana. Era un dominio de minoría, no una sustitución de la población.","textBachillerato":"Tras las guerras de los Diádocos, el imperio se fragmenta en tres grandes monarquías: Ptolomeos en Egipto, Seléucidas en Asia y los Antigónidas en Macedonia, más reinos menores como Pérgamo o el Ponto. Son monarquías de conquista: el rey no deriva su legitimidad de una tradición local ni de una asamblea, sino de la victoria y del ejército que la sostiene, de ahí el desarrollo del culto al soberano.\n\nSu gobierno fue pragmático hasta la médula. Conservaron la administración aqueménida y faraónica, incluido buena parte del personal, mantuvieron la fiscalidad previa y respetaron los cultos locales; los Ptolomeos se hicieron coronar y representar como faraones y financiaron templos egipcios. Lo griego ocupaba la corte, el ejército y la capa alta urbana, en una proporción demográfica mínima. Es un modelo de dominio colonial de minoría, y esa estructura explica tanto su eficacia fiscal como su fragilidad política.","callout":null},{"type":"section","title":"Koiné, ciudad y saber","text":"El resultado cultural más duradero fue lingüístico. La *koiné*, un griego simplificado nacido del ático con influencias jónicas, se convirtió en lengua de administración, comercio y cultura desde el Adriático hasta Bactriana. En ella se redactaron contratos en el Fayum, inscripciones en Afganistán, la traducción de los Setenta de la Biblia hebrea en Alejandría y, tres siglos después, el Nuevo Testamento.\n\nLa polis no desapareció bajo las monarquías, como sostuvo durante mucho tiempo un relato de decadencia. Perdió autonomía en política exterior, pero conservó asambleas, magistraturas, finanzas y una vida cívica intensa, ahora sostenida por el evergetismo: notables y reyes financiaban murallas, gimnasios, fiestas y reparto de grano a cambio de honores públicos. El gimnasio se volvió la institución decisiva, porque marcaba quién pertenecía al cuerpo cívico griego: se era griego, en la práctica, por educación y por acceso a esa institución, no solo por origen.\n\nAlejandría concentró el proyecto intelectual más ambicioso. El Museo era una institución de investigación financiada por la corona, con salarios y manutención, y la Biblioteca aspiraba a reunir todos los libros del mundo; las cifras de rollos que dan las fuentes antiguas, de cuatrocientos mil a setecientos mil, no son verificables. Allí nació la filología como disciplina: Zenódoto, Aristófanes de Bizancio y Aristarco de Samotracia establecieron el texto de Homero, inventaron los signos críticos para marcar versos sospechosos y sistematizaron acentuación y puntuación. Calímaco compuso los *Pínakes*, un catálogo razonado en ciento veinte libros que es el antepasado de toda bibliografía.\n\nLa ciencia helenística alcanzó cotas que Europa tardaría casi dos milenios en recuperar. Euclides sistematizó la geometría hacia 300 a. C.; Arquímedes trabajó en estática, hidrostática y métodos de exhaución; Eratóstenes midió la circunferencia terrestre comparando la sombra del sol en Siena y Alejandría, con un error que no puede evaluarse con precisión porque no conocemos el valor exacto de su estadio; Aristarco de Samos propuso un sistema heliocéntrico que conocemos sobre todo porque Arquímedes lo cita para discutirlo; Hiparco descubrió la precesión de los equinoccios y catalogó estrellas. En Alejandría, Herófilo y Erasístrato practicaron disección humana sistemática, algo excepcional en la Antigüedad, y describieron el sistema nervioso distinguiendo nervios de tendones. El mecanismo de Anticitera, un calculador astronómico de engranajes del siglo II o I a. C. recuperado del mar, demuestra que la ingeniería de precisión existía y que hemos perdido casi todo su contexto.\n\nLa filosofía se desplazó hacia la conducta individual. Zenón de Citio fundó la Estoa hacia 300 a. C., Epicuro había abierto el Jardín en 306, y junto a cínicos y escépticos compartieron una pregunta común: cómo alcanzar la imperturbabilidad en un mundo que el individuo no controla. Se ha explicado ese giro como refugio ante la pérdida de la libertad política de la polis; la explicación es discutible, porque la vida cívica siguió siendo intensa, pero el desplazamiento del centro de gravedad hacia la ética personal es innegable.\n\nEn religión convivieron el culto a los soberanos, la fortuna personificada en Tyche, los cultos mistéricos y las divinidades mixtas creadas o promovidas por los reyes, como Sarapis en Alejandría. Isis inició desde Egipto una difusión mediterránea que llegaría hasta el corazón del Imperio romano.","textEso":"Lo que de verdad quedó fue una lengua común, el griego koiné, que se hablaba desde Sicilia hasta Afganistán y en la que se escribieron el Nuevo Testamento y la primera traducción de la Biblia. Y quedaron las ciudades, con sus teatros, gimnasios y bibliotecas. Alejandría llegó a tener la mayor biblioteca de la Antigüedad y un centro de investigación, el Museo, donde trabajaron Euclides, Eratóstenes, que midió la Tierra con bastante precisión, y Arquímedes.","textBachillerato":"El resultado cultural más duradero del helenismo es la koiné, un griego simplificado que funcionó como lengua común desde Sicilia hasta el Punyab. En koiné se escribió la Septuaginta, primera traducción de la Biblia hebrea, y más tarde el Nuevo Testamento: sin esa lengua común, la difusión del cristianismo habría sido otra.\n\nEl segundo resultado es un modelo urbano exportable: ciudad con ágora, teatro, gimnasio y a veces biblioteca, reproducido por todo el Mediterráneo oriental y Asia. Y el tercero, una ciencia patrocinada por el Estado. El Museo y la Biblioteca de Alejandría, financiados por los Ptolomeos, acogen a Euclides, a Eratóstenes —que calcula la circunferencia terrestre con un error de pocos puntos porcentuales— y a Aristarco de Samos, que propone un modelo heliocéntrico dieciocho siglos antes de Copérnico. Es la primera vez que aparece algo parecido a una institución de investigación financiada con dinero público.","callout":"Aristarco de Samos propuso el heliocentrismo hacia 270 a. C. Su obra se perdió: lo sabemos porque Arquímedes resume la hipótesis para discutirla. La historia de la ciencia antigua se lee en gran parte a través de sus huecos."},{"type":"section","title":"¿Helenización o negociación?","text":"El término «helenismo» como nombre de época lo acuñó Johann Gustav Droysen entre 1836 y 1843, y con él una tesis: la fusión de Grecia y Oriente habría creado el terreno cultural en el que después arraigó el cristianismo. La idea de una helenización entendida como difusión en un solo sentido —los griegos aportan cultura, los pueblos locales la reciben— dominó la disciplina más de un siglo, y encajaba sin esfuerzo con las categorías coloniales del XIX.\n\nLa documentación local ha obligado a revisarla. El cilindro de Antíoco I de Borsipa, de 268 a. C., está escrito en acadio, en escritura cuneiforme y con el formulario de los reyes babilonios: el monarca seléucida se presenta como restaurador del templo Ezida y usa títulos que se remontan mil quinientos años atrás. La piedra de Rosetta conserva un decreto sacerdotal de Menfis de 196 a. C. en jeroglífico, demótico y griego, en el que el clero egipcio concede honores cultuales a Ptolomeo V a cambio de privilegios fiscales confirmados: es un acta de negociación entre dos poderes, no una imposición.\n\nLos diarios astronómicos babilonios siguieron redactándose en cuneiforme hasta el siglo I a. C., dos siglos después de la conquista; los templos egipcios continuaron construyéndose con formas faraónicas —Edfú, Dendera y File son en buena parte de época ptolemaica—; el derecho egipcio siguió aplicándose en tribunales propios y el demótico siguió siendo lengua de contratos. Sherwin-White y Kuhrt propusieron por eso leer los reinos helenísticos desde el interior, con sus fuentes locales, y no solo como episodios de la historia griega.\n\nEl estatuto de «griego» funcionó además como categoría jurídica y fiscal más que étnica. En Egipto determinaba a qué tribunal se acudía y qué impuestos se pagaban, y era accesible por educación, servicio y lengua, de modo que hubo egipcios que aparecen en la documentación con dos nombres, uno griego y otro egipcio, según el contexto. Al mismo tiempo, el acceso a las posiciones de mando quedó reservado durante generaciones a la minoría grecomacedonia: hubo permeabilidad cultural y una jerarquía muy firme.\n\nEl caso más discutido es Judea. La revuelta macabea de 167-164 a. C. se ha contado como el choque frontal entre helenismo y judaísmo tras las medidas de Antíoco IV contra el culto del Templo. Elias Bickerman sostuvo en 1937 que la iniciativa partió de una élite judía helenizante de Jerusalén, y que el rey intervino en un conflicto ya interno; Martin Hengel mostró en 1969 que el judaísmo de esa época estaba ya profundamente helenizado en lengua, formas literarias y organización, de manera que la oposición tajante entre ambos términos es insostenible. La lectura actual describe una guerra civil judía con intervención real, y no un choque de civilizaciones.\n\nNada de esto convierte el periodo en un idilio multicultural. Hubo conquista, expropiación de tierra, fiscalidad pesada, deportaciones y revueltas indígenas recurrentes en Egipto durante los siglos III y II. Pero el modelo explicativo válido no es la difusión, sino la negociación asimétrica entre unos conquistadores minoritarios y unas estructuras locales que ni podían ser sustituidas ni tenían intención de desaparecer.","textEso":null,"textBachillerato":"La palabra helenización sugiere que una cultura sustituye a otra, y el registro arqueológico no lo respalda. Lo que se observa es desigual y negociado: en las ciudades nuevas y entre las élites, adopción intensa de formas griegas; en el campo, continuidad de lenguas, cultos y prácticas locales durante siglos.\n\nAbundan los fenómenos mixtos. En Egipto se documentan familias que usan un nombre griego en los trámites y otro egipcio en el ámbito doméstico. Surgen divinidades compuestas como Serapis, creada deliberadamente para servir a griegos y egipcios. En Bactriana aparecen reyes greco-budistas y un arte que mezcla canon griego e iconografía india. Por eso hoy se prefiere hablar de interacción o de negociación cultural, con un matiz importante: la negociación se daba entre partes muy desiguales, porque el poder político, militar y fiscal estaba en manos de la minoría griega.","callout":null},{"type":"section","title":"El final romano y lo que quedó","text":"Roma absorbió los reinos helenísticos en siglo y medio, y en gran medida por invitación: fueron las potencias menores del Egeo, Rodas y Pérgamo, quienes la llamaron contra Macedonia. Cinoscéfalas (197) y Magnesia (190) redujeron a Antigónidas y Seléucidas; Pidna (168) liquidó el reino de Macedonia; en 146 Corinto fue destruida y Grecia quedó bajo control romano; en 133 Átalo III legó Pérgamo por testamento; Pompeyo terminó con lo que quedaba del reino seléucida en 63; y en 30, tras Accio, Egipto se convirtió en provincia con la muerte de Cleopatra VII, última soberana de una dinastía macedonia que había gobernado el país durante trescientos años.\n\nEl final es político y no cultural, y conviene subrayarlo porque la periodización engaña. El Mediterráneo oriental siguió funcionando en griego bajo dominio romano: la administración provincial, las ciudades, la filosofía, la medicina y la literatura. El Nuevo Testamento se escribió en koiné. El Imperio de Oriente que llamamos bizantino es la continuación institucional de ese mundo, y se llamaba a sí mismo romano mientras hablaba griego.\n\nLa herencia científica siguió otro camino. Los textos de Euclides, Arquímedes, Ptolomeo, Hiparco y los médicos alejandrinos fueron traducidos al siríaco y al árabe entre los siglos VIII y X, se estudiaron y corrigieron en Bagdad, El Cairo y Córdoba, y regresaron a Europa por vía latina desde el siglo XII. La cadena de transmisión que hizo posible la astronomía y la matemática europeas pasa por el helenismo y por el mundo islámico, no por una línea directa de Atenas a Florencia.\n\nQueda por último una advertencia de método. «Helenismo» y sus fechas canónicas, 323 a 30 a. C., son una construcción del siglo XIX: nadie vivió pensando que habitaba una época intermedia entre Grecia clásica y Roma. La etiqueta sigue siendo útil para nombrar un espacio y un tiempo con rasgos comunes —monarquías de conquista, koiné, ciudades nuevas, ciencia de corte—, siempre que no se confunda la etiqueta con una explicación.","textEso":"Roma fue absorbiendo los reinos helenísticos uno por uno: Macedonia en 148 a. C., el reino de Pérgamo por herencia, Siria en 64 a. C. y Egipto en 30 a. C., tras la derrota de Cleopatra. Pero la conquista fue también cultural en sentido contrario: los romanos copiaron el arte, la filosofía y la educación griegas, y las élites romanas aprendían griego. El Imperio romano de Oriente seguiría hablando griego mil años más.","textBachillerato":"La absorción romana fue gradual y desigual: Macedonia anexionada en 148 a. C. tras las guerras macedónicas, Pérgamo legado por testamento en 133 a. C., el reino seléucida reducido y anexionado por Pompeyo en 64 a. C., y Egipto incorporado en 30 a. C. tras la derrota de Cleopatra VII. El Mediterráneo oriental pasa a ser provincia, no desaparece.\n\nLo que quedó fue mucho. Roma adoptó el arte, la filosofía, la retórica y el modelo educativo griegos hasta el punto de que la frase de Horacio sobre la Grecia cautiva que cautivó a su vencedor se convirtió en tópico; el bilingüismo era normal en la élite romana. El Mediterráneo oriental siguió siendo de lengua griega bajo Roma y después durante mil años en el Imperio bizantino. Y la koiné y la red de ciudades helenísticas fueron la infraestructura sobre la que se difundió el cristianismo.","callout":null},{"type":"concepts","items":[{"term":"Sarisa","definition":"Pica macedonia de cinco a seis metros, manejada a dos manos. Daba profundidad a la falange a costa de su maniobrabilidad."},{"term":"Hetairoi","definition":"Caballería de los compañeros del rey. Arma decisiva del sistema macedonio: la falange fijaba, la caballería cargaba."},{"term":"Liga de Corinto","definition":"Alianza de las ciudades griegas bajo hegemonía macedonia (337 a. C.), con paz general y guerra declarada a Persia."},{"term":"Diádocos","definition":"Los generales sucesores de Alejandro. Sus guerras, entre 323 y 281 a. C., fijaron el mapa de los reinos helenísticos."},{"term":"Doríktetos chóra","definition":"Tierra conquistada con la lanza. Fundamento de legitimidad de la realeza helenística: el poder lo da la victoria."},{"term":"Culto al soberano","definition":"Honores divinos rendidos al rey vivo o a la dinastía. Instrumento de cohesión en monarquías sin legitimidad tradicional."},{"term":"Cleruquía","definition":"Lote de tierra concedido a un colono grecomacedonio a cambio de servicio militar. Base social del Egipto ptolemaico."},{"term":"Koiné","definition":"Griego común derivado del ático. Lengua de administración, comercio y cultura desde el Adriático hasta Bactriana."},{"term":"Evergetismo","definition":"Financiación de obras y fiestas públicas por notables y reyes a cambio de honores. Sostuvo la vida cívica bajo las monarquías."},{"term":"Gimnasio","definition":"Institución educativa que marcaba la pertenencia al cuerpo cívico griego. Ser griego dependía en gran parte del acceso a ella."},{"term":"Museo y Biblioteca","definition":"Instituciones de investigación financiadas por los Ptolomeos en Alejandría. Origen de la filología y de la bibliografía."},{"term":"Pínakes","definition":"Catálogo razonado de la Biblioteca compuesto por Calímaco en ciento veinte libros. Antepasado de todo repertorio bibliográfico."},{"term":"Ataraxia","definition":"Imperturbabilidad del ánimo. Objetivo compartido por estoicos, epicúreos y escépticos en un mundo que el individuo no controla."},{"term":"Helenización","definition":"Modelo de difusión cultural en un solo sentido, hoy sustituido por el de negociación asimétrica entre conquistadores y estructuras locales."}]},{"type":"debates","items":[{"question":"¿Qué proyecto tenía Alejandro?","positions":[{"school":"Fusión y hermandad (Tarn, 1948)","argument":"Alejandro perseguía la unidad del género humano: bodas de Susa, incorporación de persas al ejército y a la administración, adopción de usos orientales y la oración de Opis sobre la concordia entre macedonios y persas."},{"school":"Poder y violencia (Badian, 1958; Bosworth)","argument":"Las medidas de integración fueron pragmáticas: no había macedonios suficientes para gobernar un imperio así. El registro incluye la eliminación de Filotas y Parmenión, la muerte de Clito, el caso de Calístenes y matanzas civiles en Tiro, Gaza y Masaga."}],"state":"La lectura idealista está abandonada en la investigación, aunque sigue viva en la cultura popular. El límite real es documental: sin fuentes contemporáneas, cualquier reconstrucción de sus intenciones descansa sobre autores que escriben tres siglos después."},{"question":"¿Hubo helenización o negociación cultural?","positions":[{"school":"Difusión (Droysen y la tradición del siglo XIX)","argument":"La conquista extendió la lengua, las instituciones y la cultura griegas por Oriente, y esa fusión creó el terreno común sobre el que se levantaron el Imperio romano y el cristianismo."},{"school":"Negociación asimétrica (Sherwin-White y Kuhrt, 1993)","argument":"Las fuentes locales muestran continuidad: cilindro de Antíoco I en acadio con formulario babilonio, decreto sacerdotal de Rosetta, diarios astronómicos cuneiformes hasta el siglo I a. C., templos y derecho egipcios en funcionamiento. Los reyes gobernaron pactando con estructuras que no podían sustituir."}],"state":"El modelo difusionista está descartado. Se estudia cada región con su documentación propia, y la discusión se ha desplazado a medir el grado de permeabilidad: hubo movilidad cultural real y, a la vez, una jerarquía de acceso al poder muy firme."},{"question":"¿Fue la revuelta macabea un choque entre helenismo y judaísmo?","positions":[{"school":"Conflicto interno (Bickerman, 1937)","argument":"La iniciativa de las reformas partió de una élite judía helenizante de Jerusalén enfrentada a los sectores tradicionalistas. Antíoco IV intervino en un conflicto que ya existía dentro de la comunidad."},{"school":"Judaísmo ya helenizado (Hengel, 1969)","argument":"Para el siglo II a. C. el judaísmo estaba impregnado de lengua, formas literarias y organización griegas, incluida la traducción de los Setenta. Oponer helenismo y judaísmo como bloques cerrados es insostenible."}],"state":"Se describe como guerra civil judía con intervención real, no como choque de civilizaciones. Persiste la discusión sobre el peso relativo de las decisiones de Antíoco IV y de la dinámica interna de Jerusalén."}]},{"type":"timeline","items":[{"date":"359–336 a. C.","event":"Reinado de Filipo II: reforma del ejército macedonio y hegemonía sobre Grecia."},{"date":"338 a. C.","event":"Queronea: derrota de Atenas y Tebas; al año siguiente, Liga de Corinto."},{"date":"336 a. C.","event":"Asesinato de Filipo en Egas; Alejandro accede al trono."},{"date":"334–331 a. C.","event":"Gránico, Issos, asedio de Tiro, Egipto y fundación de Alejandría."},{"date":"331 a. C.","event":"Gaugamela: derrota decisiva de Darío III."},{"date":"330 a. C.","event":"Incendio de Persépolis y muerte de Darío a manos de Beso."},{"date":"326 a. C.","event":"Batalla del Hidaspes y motín del Hífasis: el ejército se niega a seguir."},{"date":"323 a. C.","event":"Muerte de Alejandro en Babilonia; comienzan las guerras de los diádocos."},{"date":"301 a. C.","event":"Ipsos: muere Antígono Monoftalmos y se frustra la reunificación del imperio."},{"date":"281 a. C.","event":"Curupedio: quedan consolidados los tres grandes reinos."},{"date":"c. 280 a. C.","event":"Museo y Biblioteca de Alejandría en pleno funcionamiento."},{"date":"268 a. C.","event":"Cilindro de Antíoco I en Borsipa, en acadio y con formulario babilonio tradicional."},{"date":"196 a. C.","event":"Decreto de Menfis, conservado en la piedra de Rosetta."},{"date":"167–164 a. C.","event":"Revuelta macabea en Judea."},{"date":"168–30 a. C.","event":"De Pidna a la anexión de Egipto: Roma absorbe uno tras otro los reinos helenísticos."}]},{"type":"sources","items":[{"author":"Arriano","title":"Anábasis de Alejandro Magno","year":"s. II d. C.","kind":"primaria","note":"Relato mejor valorado; declara seguir a Ptolomeo y Aristóbulo, ambos participantes e interesados."},{"author":"Diodoro Sículo","title":"Biblioteca histórica, libros XVII-XX","year":"s. I a. C.","kind":"primaria","note":"Fuente principal para los diádocos, además de la campaña de Alejandro."},{"author":"Plutarco","title":"Vida de Alejandro","year":"c. 100 d. C.","kind":"primaria","note":"Biografía moral, no crónica militar. Fuente de buena parte de las anécdotas célebres."},{"author":"Quinto Curcio Rufo","title":"Historia de Alejandro Magno","year":"s. I d. C.","kind":"primaria","note":"Tradición «vulgata», atenta al drama y a la degradación moral del conquistador."},{"author":"Antíoco I","title":"Cilindro de Borsipa","year":"268 a. C.","kind":"primaria","note":"En acadio y con formulario babilonio milenario: un rey seléucida como restaurador del templo Ezida."},{"author":"Clero de Menfis","title":"Decreto de Menfis (piedra de Rosetta)","year":"196 a. C.","kind":"primaria","note":"Trilingüe. Honores cultuales a Ptolomeo V a cambio de privilegios: acta de negociación, no de imposición."},{"author":"Archivo de Zenón","title":"Papiros de gestión de una finca del Fayum","year":"c. 260-240 a. C.","kind":"primaria","note":"Miles de documentos sobre la maquinaria fiscal ptolemaica y la vida rural egipcia."},{"author":"Polibio","title":"Historias","year":"s. II a. C.","kind":"primaria","note":"Griego deportado a Roma; explica a sus compatriotas cómo Roma absorbió el mundo helenístico."},{"author":"Anónimo","title":"Primer libro de los Macabeos","year":"s. II-I a. C.","kind":"primaria","note":"Relato hasmoneo de la revuelta. Fuente de parte y no crónica neutral."},{"author":"Escribas babilonios","title":"Diarios astronómicos","year":"s. VII-I a. C.","kind":"primaria","note":"Observación continuada en cuneiforme dos siglos después de la conquista macedonia."},{"author":"Johann Gustav Droysen","title":"Geschichte des Hellenismus","year":"1836-1843","kind":"estudio","note":"Acuña el término y la tesis de la fusión greco-oriental como antesala del cristianismo."},{"author":"William W. Tarn","title":"Alexander the Great","year":"1948","kind":"estudio","note":"Formula la idea de Alejandro como promotor de la hermandad de la humanidad."},{"author":"Ernst Badian","title":"Alexander the Great and the Unity of Mankind","year":"1958","kind":"estudio","note":"Demolición de la lectura de Tarn a partir del propio registro de las fuentes."},{"author":"Martin Hengel","title":"Judentum und Hellenismus","year":"1969","kind":"estudio","note":"Demuestra hasta qué punto el judaísmo del siglo II a. C. estaba ya helenizado."},{"author":"A. B. Bosworth","title":"Conquest and Empire","year":"1988","kind":"estudio","note":"Síntesis de referencia: capacidad militar y violencia sistemática, sin proyecto reconstruible."},{"author":"Peter Green","title":"Alexander to Actium","year":"1990","kind":"estudio","note":"Panorama general del periodo, crítico con la idealización del helenismo."},{"author":"Susan Sherwin-White y Amélie Kuhrt","title":"From Samarkhand to Sardis","year":"1993","kind":"estudio","note":"Relee el reino seléucida desde la documentación local y no desde las fuentes grecorromanas."},{"author":"Dorothy J. Thompson","title":"Memphis under the Ptolemies","year":"1988","kind":"estudio","note":"Convivencia de estructuras griegas y egipcias en una gran ciudad del valle del Nilo."}]},{"type":"images","items":[{"src":"/img/helenismo/portada.jpg","alt":"Detalle de mosaico romano con Alejandro Magno a caballo, coraza y lanza, cargando en la batalla","width":1200,"height":828,"role":"portada","caption":"Alejandro en el mosaico de Issos, copia romana de una pintura helenística.","author":"Ruthven ( talk · contribs )","title":"BattleofIssus333BC-mosaic-detail1","year":"2005","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:BattleofIssus333BC-mosaic-detail1.jpg"},{"src":"/img/helenismo/alejandro.jpg","alt":"Busto de mármol de un joven sin barba con el pelo levantado sobre la frente y la cabeza ligeramente girada","width":1200,"height":1823,"role":"figura","section":1,"caption":"Retrato de Alejandro, copia helenística. El giro de la cabeza y la melena se convirtieron en la imagen oficial del rey y la copiaron sus sucesores.","author":"Unknown artist Unknown artist","title":"Bust Alexander BM 1857","year":"sin fecha","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Bust_Alexander_BM_1857.jpg"},{"src":"/img/helenismo/pergamo.jpg","alt":"Gran escalinata de mármol flanqueada por un friso continuo de figuras en altorrelieve en combate","width":1200,"height":366,"role":"figura","section":2,"caption":"El altar de Pérgamo, hacia 160 a. C. La gigantomaquia del friso equipara a los reyes atálidas con los dioses frente a los bárbaros.","author":"Lestat (Jan Mehlich)","title":"Berlin - Pergamonmuseum - Altar 01","year":"2007","source":"Wikimedia Commons","license":"CC BY-SA 3.0","url":"https://commons.wikimedia.org/wiki/File:Berlin_-_Pergamonmuseum_-_Altar_01.jpg"},{"src":"/img/helenismo/nike.jpg","alt":"Estatua sin cabeza de una mujer alada con el ropaje pegado al cuerpo por el viento, de pie sobre una proa de piedra","width":1200,"height":1818,"role":"figura","section":3,"caption":"La Victoria de Samotracia, hacia 190 a. C. El pedestal es una proa de barco: conmemora una victoria naval.","author":"Autor desconocido","title":"Nike of Samothrake Louvre Ma2369 n4","year":"sin fecha","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Nike_of_Samothrake_Louvre_Ma2369_n4.jpg"}]},{"type":"documents","items":[{"section":4,"title":"Una ciudad griega en el Punyab","text":"Aquí están las palabras de Clearco, traídas desde Delfos, la escritura luminosa de los antiguos:\n\nDe niño, sé ordenado. De joven, dueño de ti mismo. En la madurez, justo. De anciano, buen consejero. Y al morir, sin pesadumbre.","source":"Inscripción del recinto de Kineas, Ai Janum (actual Afganistán), siglo III a. C.","note":"Versión propia a partir del griego. Las máximas fueron copiadas en Delfos y llevadas a más de cinco mil kilómetros.","question":"Alguien se tomó la molestia de copiar unas máximas en Grecia y grabarlas en el actual Afganistán. ¿Eso es helenización, o es otra cosa? Piensa en para quién estaba escrita esta piedra."}]}]'::jsonb, 0, true
